INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A startup is launching a new social media application and expects rapid, unpredictable user growth. They need an infrastructure that can scale quickly to handle millions of users globally without significant upfront investment. Which benefit of the AWS Cloud directly addresses this requirement?', '["Elasticity and Agility","Fixed Capital Expenditure (CapEx)","On-premises data center management","Manual hardware provisioning"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) refers to Elasticity and Agility, which are core benefits of the AWS Cloud. Elasticity allows resources to scale up or down automatically with demand, while agility enables rapid provisioning of resources, perfectly suiting unpredictable user growth without upfront investment. Option B (incorrect) is the opposite of a cloud benefit; cloud computing shifts from CapEx to Operational Expenditure (OpEx). Option C (incorrect) describes the traditional approach that the startup is trying to avoid, as it involves managing physical infrastructure. Option D (incorrect) contradicts the need for rapid scaling and agility, as manual provisioning is slow and inefficient for dynamic workloads.', 60, 'm_60_1', 1, NULL, NULL),
  ('mock_60_all_1775000080858', 'A traditional enterprise is evaluating migrating its on-premises data center to AWS. Their primary motivation is to reduce the burden of managing physical servers, power, and cooling, and to shift from large capital expenditures to operational expenses. Which AWS Cloud benefit aligns with this goal?', '["Increased CapEx for infrastructure","Reduced operational overhead and pay-as-you-go pricing","Maintaining full control over physical hardware","Long-term hardware procurement cycles"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly aligns with the benefits of migrating to AWS. Cloud computing reduces the operational overhead by offloading infrastructure management to AWS and shifts the financial model from large upfront capital expenditures (CapEx) to a pay-as-you-go operational expense (OpEx). Option A (incorrect) is the opposite of the financial benefit of cloud computing, which aims to reduce CapEx. Option C (incorrect) contradicts the goal of reducing the burden of managing physical servers, as AWS manages the underlying hardware. Option D (incorrect) describes a characteristic of on-premises environments, which cloud migration aims to overcome by enabling rapid provisioning and de-provisioning of resources.', 60, 'm_60_1', 2, NULL, NULL),
  ('mock_60_all_1775000080858', 'A global e-commerce company wants to ensure its application remains accessible even if an entire data center experiences an outage. They need to deploy their services across geographically separate locations within a region to maximize uptime. Which AWS Cloud benefit is most relevant here?', '["Single Availability Zone deployment","Reduced data transfer costs","High availability and fault tolerance","On-demand capacity planning"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) refers to high availability and fault tolerance, which are achieved by deploying applications across multiple, isolated Availability Zones within an AWS Region. This design ensures that if one data center (Availability Zone) fails, the application remains operational. Option A (incorrect) represents an anti-pattern (ap-1.2-004) as deploying to a single Availability Zone creates a single point of failure and does not provide high availability. Option B (incorrect) is a potential cost optimization benefit but not the primary one addressing application accessibility during a data center outage. Option D (incorrect) is a benefit of elasticity, but not directly related to ensuring accessibility during a data center outage across multiple locations.', 60, 'm_60_1', 3, NULL, NULL),
  ('mock_60_all_1775000080858', 'A research institution frequently runs large-scale simulations that require significant compute resources for a few hours each week. They want to pay only for the compute capacity they consume during these peak times, avoiding idle resources. Which core benefit of AWS Cloud computing supports this model?', '["Long-term contracts for reserved capacity","Upfront hardware purchases","Continuous resource provisioning","Pay-as-you-go pricing model"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the pay-as-you-go pricing model, a fundamental benefit of AWS Cloud computing. It allows customers to pay only for the compute capacity, storage, and other resources they actually use, eliminating the cost of idle resources. Option A (incorrect) refers to Reserved Instances, which offer discounts for commitment but do not perfectly align with the need to pay only for a few hours each week without commitment. Option B (incorrect) is a characteristic of on-premises infrastructure, which the cloud aims to avoid. Option C (incorrect) represents an anti-pattern (ap-1.1-004) as continuously provisioning resources for intermittent workloads negates the pay-as-you-go benefit and leads to unnecessary costs.', 60, 'm_60_1', 4, NULL, NULL),
  ('mock_60_all_1775000080858', 'A small software development firm needs to quickly provision and de-provision development and testing environments for new projects. They want to minimize the time it takes to get new infrastructure ready for developers. Which AWS Cloud benefit is most relevant to their need for speed and flexibility?', '["Agility","Reduced global infrastructure","Increased capital expenditure","Manual server configuration"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Agility, a key benefit of the AWS Cloud. Agility allows organizations to rapidly provision and de-provision resources, experiment quickly, and accelerate time-to-market, which is ideal for development and testing environments. Option B (incorrect) is contrary to AWS''s global infrastructure, which provides extensive reach. Option C (incorrect) is the opposite of a cloud benefit; cloud computing typically reduces capital expenditure. Option D (incorrect) describes a time-consuming and error-prone process that cloud computing aims to automate and eliminate, thus hindering speed and flexibility.', 60, 'm_60_1', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is designing a new critical application that must remain available even if a single server or an entire Availability Zone fails. They want to ensure continuous operation with minimal downtime. Which AWS design principle should be prioritized to meet this requirement?', '["Treating servers as pets","Design for failure","Manual scaling and provisioning","Deploying to a single Availability Zone"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is ''Design for failure'', a fundamental AWS Well-Architected Framework principle. This principle advocates building systems that anticipate and gracefully handle component failures, often by deploying across multiple Availability Zones and using redundant resources. Option A (incorrect) represents an anti-pattern (ap-1.2-001) where servers are treated as unique, irreplaceable entities, which hinders resilience and automation. Option C (incorrect) contradicts the principle of elasticity and automation, leading to slower recovery and higher operational overhead. Option D (incorrect) represents an anti-pattern (ap-1.2-004) as deploying to a single Availability Zone creates a single point of failure, making the application vulnerable to outages.', 60, 'm_60_4', 6, NULL, NULL),
  ('mock_60_all_1775000080858', 'A development team frequently deploys new versions of their application. They want to automate the provisioning and configuration of their infrastructure to ensure consistency, reduce manual errors, and speed up deployments. Which AWS design principle emphasizes this approach?', '["Manual infrastructure management","Tightly coupled architecture","Implement automation","Treating resources as unique"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is ''Implement automation'', a key AWS design principle that promotes using infrastructure as code and automated deployment pipelines. This approach ensures consistency, reduces human error, and accelerates the release cycle. Option A (incorrect) is the opposite of the desired outcome, as manual management is slow and prone to errors. Option B (incorrect) represents an anti-pattern (ap-1.2-002) as tightly coupled architectures are harder to automate, scale, and update independently. Option D (incorrect) represents an anti-pattern (ap-1.2-001) as treating resources as unique ''pets'' prevents automation and reproducibility.', 60, 'm_60_4', 7, NULL, NULL),
  ('mock_60_all_1775000080858', 'A web application experiences unpredictable traffic spikes throughout the day. The company wants its infrastructure to automatically adjust capacity to meet demand, scaling out during peak times and scaling in during off-peak hours, to optimize costs and performance. Which AWS design principle directly addresses this?', '["Provisioning for peak capacity at all times","Manual capacity planning","Designing for fixed capacity","Implement elasticity"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is ''Implement elasticity'', a core AWS design principle. Elasticity allows systems to automatically scale resources up or down based on demand, ensuring optimal performance during peak loads and cost efficiency during low usage periods. Option A (incorrect) represents an anti-pattern (ap-1.1-004) as provisioning for peak capacity at all times leads to significant unnecessary costs when demand is low. Option B (incorrect) contradicts the goal of automatic adjustment and would lead to either over-provisioning or under-provisioning. Option C (incorrect) is the opposite of elasticity and would result in performance issues during spikes or wasted resources during troughs.', 60, 'm_60_4', 8, NULL, NULL),
  ('mock_60_all_1775000080858', 'An organization is building a microservices-based application where different components handle specific tasks independently. They want to ensure that a failure in one service does not impact the entire application. Which AWS design principle is crucial for achieving this resilience?', '["Decouple components","Monolithic architecture","Centralized single point of failure","Tight coupling between services"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is ''Decouple components'', a key AWS design principle. By designing components to operate independently, a failure in one part of the system does not cascade and affect others, enhancing overall system resilience and fault tolerance. Option B (incorrect) describes a monolithic architecture, which is typically tightly coupled and prone to widespread failures from a single point of failure. Option C (incorrect) directly contradicts the goal of resilience and fault tolerance, as it introduces a single point of failure. Option D (incorrect) represents an anti-pattern (ap-1.2-002) as tight coupling means components are highly dependent on each other, making the system less resilient and harder to scale independently.', 60, 'm_60_4', 9, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is evaluating its current cloud architecture against AWS best practices to identify areas for improvement in security, reliability, and cost-effectiveness. They need a structured approach to assess and enhance their design. Which AWS framework provides guidance for this purpose?', '["AWS Cloud Development Kit (CDK)","AWS Well-Architected Framework","AWS Management Console","AWS Marketplace"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the AWS Well-Architected Framework, which provides a set of best practices across six pillars (Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability) to help organizations build secure, high-performing, resilient, and efficient infrastructure for their applications. Option A (incorrect) is a software development framework for defining cloud infrastructure as code, not a framework for architectural assessment. Option C (incorrect) is a web-based user interface for managing AWS services, not an architectural guidance framework. Option D (incorrect) is a digital catalog of third-party software, not a framework for designing cloud architectures.', 60, 'm_60_4', 10, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is moving from an on-premises data center to AWS. Historically, they made large upfront investments in servers and networking equipment every few years. They now want to shift this financial model to a recurring operational expense. Which cloud economics concept describes this change?', '["Capital Expenditure (CapEx)","Total Cost of Ownership (TCO) increase","Shift from CapEx to Operational Expenditure (OpEx)","Fixed infrastructure costs"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes the fundamental shift in cloud economics from Capital Expenditure (CapEx) to Operational Expenditure (OpEx). CapEx involves large upfront investments in physical assets, while OpEx involves paying for services as you consume them, like utility bills. Option A (incorrect) refers to the traditional on-premises spending model that the company is moving away from. Option B (incorrect) is generally not the case for cloud migration; while TCO analysis is complex, the goal is often to reduce or optimize TCO, not increase it. Option D (incorrect) is characteristic of on-premises infrastructure, whereas cloud costs are variable based on usage.', 60, 'm_60_3', 11, NULL, NULL),
  ('mock_60_all_1775000080858', 'A business is launching a new application and wants to estimate its potential AWS costs. They need a tool that can help them model different service configurations and usage patterns to understand the financial implications before deployment. Which AWS tool is designed for this purpose?', '["AWS Cost Explorer","AWS Budgets","AWS Trusted Advisor","AWS Pricing Calculator"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS Pricing Calculator, a web-based tool that allows users to estimate the cost of their AWS services based on various configurations and usage scenarios. It''s ideal for planning and understanding potential expenses before deployment. Option A (incorrect) is used for visualizing and managing existing AWS costs, not for estimating new ones. Option B (incorrect) allows users to set custom budgets and receive alerts when costs exceed thresholds, but it''s not primarily for initial cost estimation. Option C (incorrect) provides recommendations on cost optimization, security, performance, and fault tolerance for existing resources, not for upfront cost estimation.', 60, 'm_60_3', 12, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company has migrated several applications to AWS and notices that some Amazon EC2 instances are consistently underutilized. They want to optimize costs by matching their instance types and sizes more closely to the actual workload requirements. Which cost optimization principle should they apply?', '["Right-sizing resources","Provisioning for maximum capacity","Purchasing all-upfront Reserved Instances","Ignoring resource utilization metrics"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is ''Right-sizing resources'', a key cost optimization principle. It involves analyzing resource utilization and adjusting the size and type of services (like Amazon EC2 instances) to match actual workload needs, eliminating waste from over-provisioning. Option B (incorrect) represents an anti-pattern (ap-1.1-004) as provisioning for maximum capacity at all times leads to significant unnecessary costs, especially for underutilized resources. Option C (incorrect) can be a cost-saving strategy but is only effective after right-sizing has occurred and consistent usage is confirmed; it''s not the first step to address underutilization. Option D (incorrect) directly contradicts the goal of cost optimization, as ignoring metrics prevents identifying and addressing inefficiencies.', 60, 'm_60_3', 13, NULL, NULL),
  ('mock_60_all_1775000080858', 'An organization needs to run a relational database in the cloud but wants to minimize the administrative burden of patching, backups, and scaling the underlying infrastructure. They are looking for a service that handles these operational tasks automatically. Which approach aligns with cost optimization through reduced operational overhead?', '["Deploying a database on an Amazon EC2 instance and managing it manually","Using a fully managed database service like Amazon RDS","Purchasing dedicated database servers for on-premises deployment","Implementing custom scripts for database maintenance on virtual machines"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is using a fully managed database service like Amazon RDS. Managed services significantly reduce operational overhead by automating tasks such as patching, backups, and scaling, which contributes to cost optimization by freeing up staff and reducing errors. Option A (incorrect) requires significant manual effort for administration, increasing operational overhead and not aligning with the goal of minimizing burden. Option C (incorrect) is an on-premises solution, which involves high capital expenditure and operational burden, contrary to cloud benefits. Option D (incorrect) still requires significant manual effort to develop, maintain, and monitor custom scripts, which is less efficient than a fully managed service.', 60, 'm_60_3', 14, NULL, NULL),
  ('mock_60_all_1775000080858', 'A small business is concerned about unpredictable costs in the cloud. They want to ensure they only pay for the exact resources they consume, without long-term contracts or minimum commitments, especially for variable workloads. Which fundamental AWS pricing concept directly addresses this concern?', '["Reserved Instances","Savings Plans","Pay-as-you-go pricing","Volume discounts"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the pay-as-you-go pricing model, a core tenet of AWS Cloud economics. It means customers only pay for the services they use, for as long as they use them, without upfront costs or long-term commitments, which is ideal for variable workloads and concerns about unpredictable costs. Option A (incorrect) and Option B (incorrect) are pricing models that offer discounts in exchange for committing to a certain level of usage for a 1-year or 3-year term, which contradicts the desire for no long-term contracts. Option D (incorrect) refers to automatic discounts applied for higher usage, but it doesn''t eliminate the need for commitment or address the fundamental pay-as-you-go nature.', 60, 'm_60_3', 15, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A large enterprise has decided to migrate hundreds of on-premises applications to AWS. They want a structured approach that considers not just the technical aspects but also organizational readiness, governance, and security. Which AWS framework provides comprehensive guidance for this transformation?', '["AWS Well-Architected Framework","AWS Migration Hub","AWS Database Migration Service (DMS)","AWS Cloud Adoption Framework (AWS CAF)"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS Cloud Adoption Framework (AWS CAF). AWS CAF provides guidance and best practices across six perspectives (Business, People, Governance, Platform, Security, and Operations) to help organizations plan and execute a successful cloud migration and transformation. Option A (incorrect) focuses on designing and operating reliable, secure, efficient, and cost-effective cloud systems, but it''s not primarily a migration strategy framework. Option B (incorrect) is a service that provides a central location to track migration progress, not a comprehensive framework for organizational readiness. Option C (incorrect) is a specific service for migrating databases, not a broad framework for enterprise-wide cloud adoption.', 60, 'm_60_2', 16, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company has a legacy application running on an on-premises server that they want to move to AWS quickly with minimal changes. They prefer to simply move the application and its data to an Amazon EC2 instance without redesigning the architecture. Which migration strategy does this represent?', '["Rehost (Lift and Shift)","Refactor/Re-architect","Replatform (Lift and Reshape)","Retire"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is ''Rehost'', also known as ''Lift and Shift''. This migration strategy involves moving applications to AWS without making significant changes to their architecture. It''s typically the fastest way to migrate and is often used for legacy applications to quickly gain cloud benefits. Option B (incorrect) involves fundamentally changing the application''s architecture to be cloud-native, which is a more complex and time-consuming process. Option C (incorrect) involves making some cloud-native optimizations to the application during migration, but not a complete redesign. Option D (incorrect) means decommissioning applications that are no longer needed, which is not a migration strategy for active applications.', 60, 'm_60_2', 17, NULL, NULL),
  ('mock_60_all_1775000080858', 'A business needs to migrate a large, complex Oracle database from its on-premises data center to Amazon RDS for PostgreSQL. They require a service that can facilitate this heterogeneous database migration with minimal downtime. Which AWS service is specifically designed for this task?', '["AWS Application Migration Service","AWS Database Migration Service (DMS)","AWS Snowball","AWS Migration Hub"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Database Migration Service (DMS). DMS is specifically designed to help migrate databases quickly and securely to AWS, supporting both homogeneous (e.g., Oracle to Oracle) and heterogeneous (e.g., Oracle to PostgreSQL) migrations with minimal downtime. Option A (incorrect) is primarily for migrating entire servers (EC2 instances) to AWS, not specifically for database schema and data conversion. Option C (incorrect) is part of the AWS Snow Family, used for large-scale physical data transfer, not for live database migration. Option D (incorrect) provides a central dashboard to track migration progress, but it doesn''t perform the actual database migration.', 60, 'm_60_2', 18, NULL, NULL),
  ('mock_60_all_1775000080858', 'An organization needs to transfer petabytes of data from its remote on-premises facility, which has limited internet connectivity, to AWS. They are looking for a physical device that can securely transport the data offline. Which AWS service family is designed for this type of data transfer?', '["AWS Database Migration Service (DMS)","AWS Application Migration Service","AWS Snow Family","AWS Migration Hub"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Snow Family, which includes AWS Snowball, AWS Snowball Edge, and AWS Snowmobile. These services are designed for large-scale data transfer to and from AWS, particularly for environments with limited or no internet connectivity, by physically shipping ruggedized devices. Option A (incorrect) is for migrating databases, not for large-scale offline data transfer. Option B (incorrect) is for migrating entire servers to AWS, typically over a network connection. Option D (incorrect) is a dashboard for tracking migration projects, not a data transfer service itself.', 60, 'm_60_2', 19, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is planning to migrate its entire application portfolio to AWS. They want a central place to track the progress of their migrations and discover server dependencies. Which AWS service provides a unified view and management for migration projects?', '["AWS Application Migration Service","AWS Database Migration Service (DMS)","AWS Snow Family","AWS Migration Hub"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Migration Hub. It provides a single location to track the progress of application migrations across multiple AWS and partner solutions. It also helps discover on-premises server dependencies to plan migrations effectively. Option A (incorrect) is a service for migrating servers to Amazon EC2. Option B (incorrect) is for migrating databases. Option C (incorrect) is for large-scale physical data transfer. None of these provide the overarching project tracking and dependency mapping capabilities of AWS Migration Hub.', 60, 'm_60_2', 20, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 20
WHERE id = 'mock_60_all_1775000080858';

