INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A small development team has provisioned a new AWS account. The team lead needs to establish a secure access strategy, ensuring each team member has distinct permissions and that the account''s most privileged identity is protected. Which approach provides the MOST secure initial setup for user access?', '["Create individual IAM users, assign to groups with least privilege policies, enable MFA for all users, and secure the root account with MFA for infrequent tasks.","Create a single IAM user with AdministratorAccess for the entire team to share, enable MFA on this user, and keep the root account credentials in a secure vault without MFA, assuming AWS handles its protection.","Use the root account for all daily operations, enabling MFA on it, and avoid creating additional IAM users or roles to simplify access management, despite security best practices.","Create individual IAM users for each team member with full AdministratorAccess, disable MFA for convenience, and rely solely on AWS CloudTrail for auditing purposes."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) follows AWS best practices by creating individual IAM users, applying the principle of least privilege through IAM groups and policies, enabling Multi-Factor Authentication (MFA) for all users, and securing the root account with MFA, using it only for tasks that explicitly require root privileges. Option B (incorrect) violates the principle of individual accountability and least privilege by sharing a single user with AdministratorAccess, and incorrectly assumes AWS protects root account credentials without MFA. Option C (incorrect) is an anti-pattern as the root account has unrestricted access and should never be used for daily operations. Option D (incorrect) grants overly broad permissions (AdministratorAccess) and neglects a critical security control (MFA), making the account highly vulnerable.', 61, 'm_61_3', 1, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is deploying an application on Amazon EC2 instances that requires access to Amazon S3 for data storage. The security policy strictly prohibits embedding long-term AWS credentials directly into the application code. Which AWS IAM capability should be used to grant the EC2 instances secure access to Amazon S3?', '["Attach an IAM role with necessary S3 permissions to the Amazon EC2 instances.","Generate IAM user access keys with S3 permissions and store them in an encrypted file on the EC2 instance''s local disk, rotating them regularly.","Create an IAM user with S3 access, embed its access key and secret key directly into the application''s source code, and rotate them quarterly to mitigate risk.","Use AWS Secrets Manager to store the IAM user credentials and retrieve them programmatically from the EC2 instances at runtime, ensuring secure storage."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most secure and recommended method. IAM roles provide temporary credentials that are automatically rotated and managed by AWS, eliminating the need to embed long-term access keys in application code. Option B (incorrect) still involves managing long-term access keys, even if encrypted locally, which is less secure than using roles. Option C (incorrect) is a severe anti-pattern (ap-2.3-005) as embedding credentials in code is highly insecure and difficult to manage. Option D (incorrect) while AWS Secrets Manager is good for managing secrets, using IAM roles for EC2 instances to access other AWS services is the idiomatic and most secure approach, as it avoids explicit credential management entirely for the instance.', 61, 'm_61_3', 2, NULL, NULL),
  ('mock_60_all_1775000080858', 'An organization managing several AWS accounts with AWS Organizations wants to enforce Multi-Factor Authentication (MFA) for all IAM users accessing the AWS Management Console across all member accounts. This enforcement must apply universally, overriding individual account settings. Which AWS service can achieve this with the MINIMAL administrative effort?', '["Implement a Service Control Policy (SCP) in AWS Organizations denying console access without MFA.","Manually configure an IAM policy in each member account to require MFA for console access for all IAM users, which is time-consuming.","Use AWS IAM Identity Center (SSO) to manage all user access, as it inherently enforces MFA for all federated users and simplifies management.","Deploy an AWS Lambda function that periodically checks IAM user configurations and automatically enables MFA for non-compliant users, requiring custom development."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) allows organizations to centrally enforce security policies across all member accounts, including MFA requirements, by using Service Control Policies (SCPs). SCPs act as guardrails, defining the maximum available permissions for accounts in an Organization, regardless of individual IAM policies. Option B (incorrect) would be administratively intensive and prone to errors, as it requires manual configuration in every account and wouldn''t override future IAM policy changes. Option C (incorrect) is excellent for centralized access management and federation, but an SCP provides a broader, organizational-level enforcement mechanism for *all* IAM users, even those not managed by SSO. Option D (incorrect) is an overly complex and reactive solution that requires custom development and maintenance, rather than leveraging a native AWS Organizations feature for preventative control.', 61, 'm_61_3', 3, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company''s security policy dictates that all access to AWS resources must utilize temporary, scoped credentials, minimizing the use of long-term access keys. Developers require different permission sets for various tasks, such as read-only access for auditing and administrative access for deployments. Which IAM feature best facilitates granting these temporary, scoped permissions with the LEAST management overhead?', '["IAM roles, allowing users to assume a role with specific, temporary permissions.","Creating multiple IAM users for each developer, each with different long-term access keys and distinct permission sets for various tasks.","Attaching broad IAM policies like `AdministratorAccess` directly to individual IAM users and relying on careful user behavior to prevent misuse.","Implementing a custom script that generates temporary access keys for IAM users on demand, and distributes them securely to developers."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most effective solution. IAM roles enable users to temporarily assume a set of permissions for specific tasks, providing temporary credentials that automatically expire. This adheres to the principle of least privilege and eliminates the need for long-term access keys. Option B (incorrect) would create significant management overhead due to the proliferation of IAM users and long-term credentials. Option C (incorrect) violates the principle of least privilege (ap-2.3-002) by granting overly broad permissions, increasing the blast radius in case of compromise. Option D (incorrect) would introduce custom operational overhead and complexity, which is less efficient and secure than using native IAM role capabilities.', 61, 'm_61_3', 4, NULL, NULL),
  ('mock_60_all_1775000080858', 'A large enterprise aims to centralize identity management for its AWS accounts, allowing employees to use their existing corporate Active Directory credentials to access AWS services. The objective is to enable this federated access with MINIMAL duplication of user management efforts. Which AWS service is best suited to achieve this goal?', '["AWS IAM Identity Center (SSO) integrated with the corporate Active Directory.","Manually creating individual IAM users in each AWS account and synchronizing passwords with Active Directory, which creates significant overhead.","Using the AWS root account for all corporate users and managing access through a shared password policy, which is a major security risk.","Creating an AWS Directory Service for Microsoft Active Directory and configuring trust relationships with each AWS account for authentication."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is designed for centralized access management across multiple AWS accounts and applications, allowing integration with existing corporate directories like Active Directory. This enables employees to use their existing credentials for federated access with minimal user management duplication. Option B (incorrect) would result in significant administrative overhead and does not provide true federation. Option C (incorrect) is a severe security anti-pattern (ap-2.3-001, ap-2.3-003) as the root account should never be used for daily operations or shared. Option D (incorrect) creates a managed Active Directory in AWS, which can be part of a federation solution, but AWS IAM Identity Center (SSO) is the overarching service for centralized access management to multiple AWS accounts and applications.', 61, 'm_61_3', 5, NULL, NULL),
  ('mock_60_all_1775000080858', 'A small development team needs to access an AWS account for daily operations. They require individual access credentials, adherence to the principle of least privilege, and enhanced security for their administrative users. Which approach best meets these requirements while ensuring accountability and secure access?', '["Create individual IAM users for each team member, assign them to IAM groups with specific policies, and enforce Multi-Factor Authentication (MFA) for administrative users.","Share the AWS account root user credentials among the team members and enable MFA on the root account for all administrative tasks.","Create a single IAM user with AdministratorAccess policy and share its access key and secret access key with all team members.","Use AWS IAM Identity Center to manage access, but allow users to create their own IAM policies for flexibility, without enforcing MFA."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) aligns with AWS best practices for access management. Creating individual IAM users ensures accountability, assigning them to IAM groups allows for centralized permission management following the principle of least privilege, and enforcing MFA significantly enhances security for administrative access. Option B (incorrect) is an anti-pattern ([ap-2.3-001]) as the root account should only be used for tasks that specifically require root privileges and not for daily operations, and sharing credentials violates accountability. Option C (incorrect) is an anti-pattern ([ap-2.3-003] and [ap-2.3-002]) because sharing credentials eliminates accountability and granting AdministratorAccess to a shared user violates the principle of least privilege, increasing the blast radius in case of compromise. Option D (incorrect) is an anti-pattern ([ap-2.3-004]) because while IAM Identity Center is good for centralized access, allowing users to create their own policies can lead to overly permissive access, and not enforcing MFA for administrative users leaves a significant security vulnerability.', 61, 'm_61_3', 6, NULL, NULL),
  ('mock_60_all_1775000080858', 'A new application deployed on an Amazon EC2 instance needs to securely access Amazon S3 buckets to store and retrieve data. The development team wants to ensure that the EC2 instance has the necessary permissions without embedding long-term credentials directly into the application code. Which AWS IAM feature should be used to grant these permissions following best practices?', '["Attach an IAM role to the Amazon EC2 instance with policies granting access to Amazon S3.","Generate an IAM user''s access key and secret access key, then store them in the application code on the EC2 instance.","Create an IAM group with S3 access policies and add the EC2 instance to this group.","Use the root user credentials for the EC2 instance to access Amazon S3, as it has full administrative privileges."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the AWS best practice for granting permissions to EC2 instances. By attaching an IAM role, the instance automatically receives temporary credentials that are rotated regularly, eliminating the need to store long-term access keys in the application code. This enhances security and simplifies credential management. Option B (incorrect) is an anti-pattern ([ap-2.3-005]) because embedding long-term access keys in application code is a security risk; if the code is compromised, the keys can be exposed. Option C (incorrect) is not how IAM groups work with EC2 instances; IAM groups are for organizing IAM users, not for assigning permissions directly to EC2 instances. Option D (incorrect) is an anti-pattern ([ap-2.3-001]) as the root user should never be used for daily operational tasks or application access due to its unrestricted permissions and the security risks involved.', 61, 'm_61_3', 7, NULL, NULL),
  ('mock_60_all_1775000080858', 'A large enterprise with multiple AWS accounts wants to centralize access management for its employees. They need a solution that allows employees to sign in once with their corporate credentials and gain access to all authorized AWS accounts and applications without managing individual IAM users in each account. Which AWS service is best suited for this requirement?', '["AWS IAM Identity Center (SSO) integrated with their corporate directory.","Creating a separate IAM user in each AWS account for every employee.","Using Amazon Cognito to manage user pools and federate access to AWS accounts.","Configuring AWS Directory Service to create a new directory for each AWS account."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the ideal solution. AWS IAM Identity Center (SSO) provides a centralized place to manage access to multiple AWS accounts and business applications. It allows users to sign in once with their corporate credentials (e.g., from Active Directory or Okta) and gain federated access, eliminating the need to manage individual IAM users in each account. Option B (incorrect) would be an operational nightmare for a large enterprise, requiring significant manual effort to manage users and permissions across many accounts. Option C (incorrect) is primarily for managing user authentication for web and mobile applications, not for centralized access to AWS accounts for enterprise employees. Option D (incorrect) would create multiple isolated directories, which goes against the goal of centralized access management for a single corporate identity.', 61, 'm_61_3', 8, NULL, NULL),
  ('mock_60_all_1775000080858', 'A new team of developers is joining a company and needs access to specific AWS resources, such as Amazon S3 buckets and Amazon DynamoDB tables, to perform their tasks. The security administrator wants to grant them the necessary permissions efficiently while adhering to the principle of least privilege. Which IAM feature should the administrator use to manage permissions for this group of developers?', '["Create individual IAM users for each developer and attach separate, unique policies to each user.","Create an IAM group, attach a policy with the required permissions to the group, and add all developers'' IAM users to this group.","Provide all developers with the AWS account root user credentials, as it has full access to all services.","Generate a single IAM role with AdministratorAccess and share its temporary credentials among the developers."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most efficient and secure way to manage permissions for a group of users with similar access needs. By creating an IAM group, attaching a policy with the principle of least privilege, and adding developers to this group, permissions can be managed centrally. Option A (incorrect) would be highly inefficient and prone to errors for a team, as managing individual policies for each user becomes complex. Option C (incorrect) is an anti-pattern ([ap-2.3-001]) and a severe security risk; the root user should never be used for daily tasks or shared. Option D (incorrect) is an anti-pattern ([ap-2.3-002] and [ap-2.3-003]) because granting AdministratorAccess violates the principle of least privilege, and sharing credentials eliminates accountability and increases security risks.', 61, 'm_61_3', 9, NULL, NULL);

