INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is deploying a new web application on Amazon EC2 instances within a Virtual Private Cloud (VPC). They need to control inbound and outbound traffic at both the instance level and the subnet level to enhance security. Which combination of AWS networking features should be used to achieve this defense-in-depth strategy?', '["Utilize AWS WAF for instance-level protection and AWS Shield for subnet-level traffic filtering.","Configure Security Groups for instance-level stateful filtering and Network Access Control Lists (NACLs) for subnet-level stateless filtering.","Implement Amazon GuardDuty for instance-level anomaly detection and AWS Firewall Manager for subnet-level rule enforcement.","Apply IAM policies to control access to EC2 instances and use Amazon Inspector for network vulnerability scanning."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes the appropriate use of Security Groups and Network Access Control Lists (NACLs) for a defense-in-depth strategy. Security Groups operate at the instance level, are stateful, and control traffic to and from instances. NACLs operate at the subnet level, are stateless, and control traffic entering and exiting subnets, providing an additional layer of network security. Option A (incorrect) misapplies services; AWS WAF protects web applications at the application layer, and AWS Shield provides DDoS protection, neither of which are primarily for instance-level or subnet-level traffic filtering in the manner described. Option C (incorrect) uses services for different purposes; Amazon GuardDuty is for threat detection, and AWS Firewall Manager is for centralized management of firewall rules across accounts, not for direct instance/subnet traffic filtering. Option D (incorrect) involves IAM for access control and Amazon Inspector for vulnerability assessment, which are important for security but do not directly control network traffic at the instance or subnet level.', 61, 'm_61_4', 10, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is concerned about potential unauthorized activity and threats within its AWS account, such as cryptocurrency mining, compromised instances, or unusual API calls. They need a service that can continuously monitor their AWS environment for these types of malicious activities and deliver actionable security findings with minimal effort. Which AWS service is designed for this purpose?', '["AWS WAF, to block suspicious IP addresses and protect against common web exploits.","Amazon GuardDuty, to provide intelligent threat detection by continuously monitoring for malicious activity and unauthorized behavior.","AWS Shield Advanced, to provide enhanced DDoS protection for all applications.","Amazon Inspector, to automatically assess applications for vulnerabilities and deviations from best practices."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes Amazon GuardDuty''s primary function. GuardDuty is a threat detection service that continuously monitors for malicious activity and unauthorized behavior to protect AWS accounts and workloads. It uses machine learning, anomaly detection, and integrated threat intelligence to identify threats like cryptocurrency mining, compromised instances, and unusual API calls. Option A (incorrect) is for web application firewall capabilities, protecting against common web exploits, not for general threat detection across the AWS account. Option C (incorrect) provides DDoS protection, which is a different security concern than detecting malicious activity within the account. Option D (incorrect) is for vulnerability management and assessing applications for security vulnerabilities, not for continuous threat detection of malicious activity or unauthorized behavior.', 61, 'm_61_4', 11, NULL, NULL),
  ('mock_60_all_1775000080858', 'A media company stores vast amounts of unstructured data, including customer feedback and financial records, in Amazon S3 buckets. They need to identify and classify sensitive data, such as Personally Identifiable Information (PII), to ensure compliance with data privacy regulations. Manually reviewing this data is impractical due to its volume. Which AWS service can automate this discovery process?', '["Amazon GuardDuty, to detect unusual access patterns to S3 buckets containing sensitive data.","Amazon Macie, to discover, classify, and protect sensitive data stored in Amazon S3.","Amazon Inspector, to assess the security and compliance of the EC2 instances accessing the S3 data.","AWS CloudTrail, to log all data access events to S3 buckets for manual review."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the purpose of Amazon Macie. Amazon Macie is a data security and data privacy service that uses machine learning and pattern matching to discover, classify, and protect sensitive data in AWS, primarily within Amazon S3. It helps identify PII and other sensitive information. Option A (incorrect) is for threat detection and anomaly monitoring across the AWS account, not specifically for discovering sensitive data content within S3 objects. Option C (incorrect) is for vulnerability management of EC2 instances, not for analyzing data content in S3. Option D (incorrect) logs API calls and data events, but it does not automatically classify or identify sensitive data within the content; it would still require manual review of logs, which the scenario explicitly states is impractical.', 61, 'm_61_4', 12, NULL, NULL),
  ('mock_60_all_1775000080858', 'A security team manages multiple AWS accounts and utilizes various security services like Amazon GuardDuty, Amazon Inspector, and Amazon Macie. They are struggling to get a consolidated view of all security findings, as they are spread across different service consoles. They need a centralized service to aggregate, organize, and prioritize security alerts from these services. Which AWS service provides this capability?', '["AWS CloudTrail, to log all security-related API calls and events.","AWS Security Hub, to provide a comprehensive view of security alerts and compliance status across AWS accounts.","Amazon Detective, to investigate potential security issues and identify the root cause of findings.","AWS Config, to continuously monitor and record AWS resource configurations and changes for security compliance."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) describes AWS Security Hub''s core functionality. AWS Security Hub provides a comprehensive view of your security alerts and security posture across your AWS accounts. It collects security data from various AWS services (like GuardDuty, Inspector, Macie) and partner solutions, aggregates findings, and helps you prioritize and take action. Option A (incorrect) logs API calls and events, which is crucial for auditing, but it does not aggregate and prioritize security findings from multiple services. Option C (incorrect) is for investigating security findings and performing root cause analysis, not for centralizing the initial aggregation of findings. Option D (incorrect) monitors resource configurations for compliance, but it does not aggregate security findings from other services into a single dashboard.', 61, 'm_61_4', 13, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_61_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A financial services company needs to ensure that all API calls made to their AWS account are logged for auditing purposes, and that changes to resource configurations are tracked over time to maintain compliance with regulatory requirements. They also need to access compliance reports from AWS. Which combination of AWS services will best meet these governance and compliance needs?', '["Enable Amazon GuardDuty for API call logging and Amazon Macie for configuration tracking, then use AWS Trusted Advisor for compliance reports.","Utilize AWS Shield for API call logging and AWS WAF for configuration tracking, accessing compliance reports through the AWS Management Console.","Enable AWS CloudTrail for API call logging and AWS Config for configuration tracking, and access compliance reports through AWS Artifact.","Implement AWS Security Hub for API call logging and Amazon Detective for configuration tracking, while relying on third-party auditors for compliance reports."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides the most suitable combination of services. AWS CloudTrail logs all API calls made to an AWS account, providing an audit trail for actions. AWS Config continuously monitors and records AWS resource configurations and changes, crucial for compliance. AWS Artifact is the go-to service for accessing AWS''s compliance reports and certifications. Option A (incorrect) misuses services; Amazon GuardDuty is for threat detection, Amazon Macie is for sensitive data discovery, and AWS Trusted Advisor provides recommendations, none of which directly log API calls, track configurations, or provide AWS compliance reports in the required manner. Option B (incorrect) misuses services; AWS Shield and AWS WAF are for DDoS and web application protection, respectively, and are not for API call logging or configuration tracking. Option D (incorrect) misuses services; AWS Security Hub aggregates security findings, and Amazon Detective helps investigate security incidents, neither of which are primary services for API call logging or configuration tracking. Relying solely on third-party auditors without AWS Artifact misses direct access to AWS''s own compliance documentation.', 61, 'm_61_2', 14, NULL, NULL),
  ('mock_60_all_1775000080858', 'A healthcare startup stores sensitive patient data in Amazon S3. To meet HIPAA compliance requirements, all data must be encrypted at rest with keys that the customer manages, and the encryption process must be auditable. The solution should also minimize the operational burden of key management. Which AWS service should be used to manage the encryption keys?', '["Store encryption keys directly in the Amazon S3 bucket alongside the encrypted data, secured by S3 bucket policies.","Implement client-side encryption using an open-source library and manage the encryption keys on an Amazon EC2 instance.","Utilize AWS Key Management Service (KMS) with customer-managed keys (CMKs) to encrypt the data in Amazon S3.","Use AWS Certificate Manager (ACM) to generate and manage the encryption keys for Amazon S3."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best solution. AWS Key Management Service (KMS) allows customers to create and manage encryption keys, including customer-managed keys (CMKs), which can be used to encrypt data in Amazon S3. KMS provides centralized, auditable key management with automatic key rotation and integration with AWS services, minimizing operational burden while meeting compliance requirements. Option A (incorrect) is an anti-pattern ([ap-2.2-003]) because storing encryption keys alongside the data they protect defeats the purpose of encryption and is a significant security risk. Option B (incorrect) would increase operational overhead significantly, as the customer would be responsible for managing the key lifecycle, security, and availability of the EC2 instance and the custom encryption solution, which contradicts the goal of minimizing operational burden. Option D (incorrect) is incorrect because AWS Certificate Manager (ACM) is used for managing SSL/TLS certificates, not for data encryption keys for services like Amazon S3.', 61, 'm_61_2', 15, NULL, NULL),
  ('mock_60_all_1775000080858', 'A global corporation operates multiple AWS accounts organized under AWS Organizations. The security team needs to enforce mandatory security policies across all accounts, preventing any account from performing specific prohibited actions, regardless of the IAM permissions defined within those accounts. Which AWS Organizations feature should they use to implement these preventative guardrails?', '["Apply IAM policies directly to individual IAM users and roles in each account.","Use AWS Config rules to detect non-compliant resource configurations across accounts.","Implement Service Control Policies (SCPs) within AWS Organizations to define the maximum available permissions for accounts.","Configure Amazon GuardDuty to alert on prohibited actions performed in any account."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the intended use case for Service Control Policies (SCPs). SCPs are a feature of AWS Organizations that allow you to centrally manage permissions across multiple accounts. They define the maximum available permissions for all IAM users and roles in an account, acting as guardrails that restrict actions even if an IAM policy grants broader permissions. Option A (incorrect) would be cumbersome and prone to error in a multi-account environment, as it doesn''t provide a centralized, preventative control across all accounts. Option B (incorrect) is for detecting non-compliance after an action has occurred, not for preventing actions. Option D (incorrect) is for threat detection and alerting, not for preventing actions from being performed in the first place.', 61, 'm_61_2', 16, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is undergoing a security audit and needs to provide evidence of AWS''s compliance with various global security standards and certifications, such as SOC reports, PCI DSS, and ISO certifications. They need a self-service portal to access these documents and agreements directly from AWS. Which AWS service provides this functionality?', '["AWS Trusted Advisor, which offers recommendations for security, cost optimization, and performance.","AWS Security Hub, which aggregates security findings from various AWS services.","AWS Artifact, which provides on-demand access to AWS''s security and compliance reports.","AWS CloudTrail, which logs API calls and account activity for auditing purposes."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary purpose of AWS Artifact. AWS Artifact is your go-to, central resource for security and compliance-related information that matters to you, including AWS''s compliance reports (like SOC, PCI DSS, ISO) and agreements. Option A (incorrect) provides recommendations for optimizing AWS resources, not direct access to compliance reports. Option B (incorrect) aggregates security findings from various AWS services into a single dashboard, but it does not provide AWS''s compliance certifications or reports. Option D (incorrect) logs API calls and events, which is essential for customer-side auditing, but it does not provide AWS''s own compliance documentation.', 61, 'm_61_2', 17, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_61_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is planning to deploy a new application on AWS. They are considering using both Amazon EC2 instances and Amazon RDS for their database. The security team needs a clear understanding of who is responsible for patching the operating system and the database engine. According to the AWS Shared Responsibility Model, what are the respective responsibilities?', '["AWS is responsible for patching the operating system on both Amazon EC2 instances and Amazon RDS database engines.","The customer is responsible for patching the operating system on Amazon RDS, while AWS is responsible for patching the EC2 instance operating system.","The customer is responsible for patching the operating system on Amazon EC2 instances, and AWS is responsible for patching the Amazon RDS database engine.","The customer is responsible for patching both the operating system on Amazon EC2 instances and the Amazon RDS database engine."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) accurately describes the shared responsibility model for EC2 and RDS. For Amazon EC2 (an IaaS service), the customer is responsible for the operating system, including patching, security updates, and application-level security. For Amazon RDS (a managed service), AWS is responsible for the underlying infrastructure, including the operating system and the database engine patching and updates. Option A (incorrect) misrepresents the customer''s responsibility for EC2 OS patching. Option B (incorrect) reverses the responsibilities for both services. Option D (incorrect) misrepresents AWS''s responsibility for patching the RDS database engine, which is a key benefit of using a managed service.', 61, 'm_61_1', 18, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company stores highly confidential customer data in Amazon S3. They are responsible for ensuring that this data is encrypted at rest. According to the AWS Shared Responsibility Model, which party is primarily accountable for encrypting the data stored in the S3 buckets?', '["AWS is solely responsible for encrypting all customer data stored in Amazon S3.","The customer is solely responsible for encrypting their data stored in Amazon S3.","AWS and the customer share responsibility equally for encrypting data, with AWS providing the encryption mechanisms and the customer enabling them.","The responsibility for data encryption depends on the S3 storage class used; AWS encrypts for some, customer for others."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) accurately reflects the customer''s responsibility under the AWS Shared Responsibility Model. While AWS provides the services and features (like S3 server-side encryption with S3-managed keys, KMS, or customer-provided keys) that enable data encryption, the customer is ultimately responsible for deciding to encrypt their data and configuring the appropriate encryption method. This falls under ''security IN the cloud.'' Option A (incorrect) is an anti-pattern ([ap-2.1-001]) as it assumes AWS handles all security, including customer data encryption, which is not true. Option C (incorrect) is partially true in that AWS provides the tools, but the primary accountability for enabling and managing encryption for customer data lies with the customer. Option D (incorrect) is not accurate; data encryption responsibility does not vary by S3 storage class.', 61, 'm_61_1', 19, NULL, NULL),
  ('mock_60_all_1775000080858', 'A software company is developing a new serverless application using AWS Lambda. They are concerned about the security of the underlying infrastructure that runs their Lambda functions. According to the AWS Shared Responsibility Model, who is responsible for the security of the Lambda execution environment, including the underlying operating system and hardware?', '["The customer is fully responsible for securing the Lambda execution environment, including patching the operating system.","AWS is responsible for securing the Lambda execution environment, including the underlying operating system and hardware.","The responsibility is shared, with AWS securing the hardware and the customer securing the operating system of the Lambda environment.","The responsibility depends on the programming language used for the Lambda function; customer for some, AWS for others."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) accurately reflects the AWS Shared Responsibility Model for serverless services like AWS Lambda. For serverless computing, AWS takes on more of the ''security IN the cloud'' responsibilities, including the underlying operating system, platform, and hardware that run the Lambda functions. The customer is responsible for their code, data, and configuration of the Lambda function itself. Option A (incorrect) would be true for IaaS services like EC2, but not for serverless services where AWS manages the underlying infrastructure. Option C (incorrect) misrepresents the division of responsibility for serverless environments; AWS manages the entire execution environment up to the application code. Option D (incorrect) is incorrect; the shared responsibility model for Lambda does not change based on the programming language.', 61, 'm_61_1', 20, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is hosting its application on Amazon EC2 instances within an AWS Region. They are concerned about the physical security of the data centers where their instances run. According to the AWS Shared Responsibility Model, which party is responsible for the physical security of the facilities, hardware, and global network infrastructure?', '["The customer is fully responsible for the physical security of the data centers where their EC2 instances are hosted.","The customer and AWS share responsibility equally for the physical security of the data centers.","AWS is responsible for the physical security of the facilities, hardware, and global network infrastructure.","Third-party auditors are responsible for the physical security, as AWS outsources this aspect."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) accurately describes AWS''s responsibility under the Shared Responsibility Model. AWS is responsible for ''security OF the cloud,'' which includes the physical security of the data centers, hardware, networking, and the virtualization infrastructure. The customer is responsible for ''security IN the cloud,'' which includes their data, operating systems, applications, and network configurations (like security groups). Option A (incorrect) misrepresents the shared responsibility model; customers do not have physical access or responsibility for AWS data centers. Option B (incorrect) is too broad; while some responsibilities are shared, physical security is almost entirely AWS''s domain. Option D (incorrect) is incorrect; while third-party auditors verify AWS''s security, AWS itself is directly responsible for the physical security.', 61, 'm_61_1', 21, NULL, NULL);

