INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A small startup wants to deploy its web application on AWS with the LEAST operational overhead for managing the underlying servers. The application is built on common web technologies like Node.js and requires a managed environment where patching, scaling, and load balancing are handled automatically. Which AWS service should the startup choose?', '["AWS Elastic Beanstalk","Amazon EC2 with Auto Scaling and Elastic Load Balancing","AWS Lambda with Amazon API Gateway","Amazon Lightsail"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) AWS Elastic Beanstalk is a Platform as a Service (PaaS) offering that automates the deployment, scaling, and management of web applications and services. It handles infrastructure provisioning, load balancing, auto scaling, and application health monitoring, significantly reducing operational overhead for server management. Option B (incorrect) using Amazon EC2 with Auto Scaling and Elastic Load Balancing provides flexibility but requires the user to manage the EC2 instances, including operating system patching and updates, which increases operational overhead compared to Elastic Beanstalk. Option C (incorrect) AWS Lambda with Amazon API Gateway is a serverless compute option, but the scenario describes a web application built on common web technologies that benefit from a managed application platform, not necessarily an event-driven function. While serverless, it might require more re-architecture for an existing web app than Elastic Beanstalk. Option D (incorrect) Amazon Lightsail is designed for simple web applications and virtual private servers, offering a simplified management experience, but it still requires more server management than Elastic Beanstalk, which fully abstracts the underlying infrastructure.', 62, 'm_62_1', 1, NULL, NULL),
  ('mock_60_all_1775000080858', 'A development team needs to automate the provisioning of AWS resources for their testing environments to ensure consistency and repeatability. They want to define their infrastructure as code using a declarative language and integrate it into their CI/CD pipeline. Which AWS service is BEST suited for this requirement?', '["AWS Management Console","AWS CloudFormation","AWS CLI","AWS SDKs"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) AWS CloudFormation allows users to define their AWS infrastructure as code using templates. This enables consistent, repeatable, and automated provisioning of resources, which is ideal for integration into CI/CD pipelines and ensuring environment consistency. Option A (incorrect) the AWS Management Console is a web-based interface for interacting with AWS services manually. While useful for exploration, it is an anti-pattern for production environments due to lack of automation, repeatability, and auditability. Option C (incorrect) the AWS CLI provides command-line access to AWS services. While it can be scripted for automation, it is imperative rather than declarative and does not manage the state of the infrastructure as comprehensively as CloudFormation. Option D (incorrect) AWS SDKs allow programmatic interaction with AWS services from various programming languages. Similar to the CLI, they are imperative and require more custom code to manage infrastructure state and dependencies compared to CloudFormation.', 62, 'm_62_1', 2, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is considering migrating some of its on-premises applications to AWS while maintaining direct, private network connectivity to its existing data center for specific regulatory and latency requirements. They need a solution that provides a dedicated, high-bandwidth connection. Which connectivity option should they choose?', '["Internet Gateway","AWS VPN","AWS Direct Connect","NAT Gateway"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) AWS Direct Connect provides a dedicated, private network connection from a customer''s on-premises data center to AWS. This offers consistent network performance, reduced bandwidth costs, and is ideal for hybrid cloud architectures with high-throughput or latency-sensitive workloads. Option A (incorrect) an Internet Gateway allows resources in a VPC to connect to the internet, but it does not provide a private connection to an on-premises data center. Option B (incorrect) AWS VPN establishes an encrypted connection over the public internet. While it provides connectivity, it does not offer the same dedicated bandwidth or consistent performance as AWS Direct Connect, making it less suitable for high-throughput, latency-sensitive requirements. Option D (incorrect) a NAT Gateway allows instances in a private subnet to connect to the internet or other AWS services, but it does not facilitate direct connectivity between an on-premises data center and a VPC.', 62, 'm_62_1', 3, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A global e-commerce company wants to ensure its web application remains available even if an entire data center experiences an outage. The application must serve customers worldwide with minimal latency and high fault tolerance. Which AWS global infrastructure component should be leveraged to achieve this goal?', '["AWS Local Zones","AWS Availability Zones","AWS Edge Locations","AWS Regions"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) AWS Regions are geographically isolated areas that contain multiple Availability Zones. Deploying an application across multiple AWS Regions provides the highest level of fault tolerance and disaster recovery, ensuring that an outage in one entire data center (Region) does not affect the application''s availability globally. Option A (incorrect) AWS Local Zones extend an AWS Region into a geographic area closer to users, providing low-latency access, but they are still part of a single Region and do not protect against a full Region outage. Option B (incorrect) AWS Availability Zones are isolated locations within an AWS Region. Deploying across multiple AZs provides high availability within a single Region, protecting against single data center failures, but not against an entire Region outage. Option C (incorrect) AWS Edge Locations are used by services like Amazon CloudFront to cache content closer to end-users, reducing latency for content delivery, but they do not host full application infrastructure or provide fault tolerance for the application''s core services.', 62, 'm_62_2', 4, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is launching a new customer-facing application and requires high availability and fault tolerance within a single geographic area. They need to ensure that their application can withstand the failure of a single data center. Which AWS global infrastructure design principle should they follow?', '["Deploy resources across multiple Availability Zones within a Region.","Deploy all resources in a single Availability Zone to simplify management.","Distribute resources across multiple AWS Regions for global reach.","Utilize AWS Edge Locations for application hosting."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) deploying resources across multiple Availability Zones (AZs) within a single AWS Region is the recommended approach for achieving high availability and fault tolerance. Each AZ is an isolated location within a Region, designed to be independent of failures in other AZs. Option B (incorrect) deploying all resources in a single Availability Zone creates a single point of failure. If that AZ experiences an outage, the entire application would become unavailable, violating the high availability requirement. Option C (incorrect) distributing resources across multiple AWS Regions provides disaster recovery and global availability, but the requirement specifically asks for high availability within a single geographic area, which is primarily addressed by multiple AZs. Option D (incorrect) AWS Edge Locations are primarily used for content delivery networks (CDNs) like Amazon CloudFront and DNS services like Amazon Route 53. They are not designed for hosting entire applications or providing the core compute and database infrastructure.', 62, 'm_62_2', 5, NULL, NULL),
  ('mock_60_all_1775000080858', 'A media company wants to deliver video content to its global audience with the lowest possible latency. They need a solution that caches content close to their users worldwide. Which AWS service is specifically designed for this purpose?', '["Amazon EC2","Amazon CloudFront","Amazon S3","AWS Direct Connect"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon CloudFront is a content delivery network (CDN) service that securely delivers data, videos, applications, and APIs to customers globally with low latency and high transfer speeds. It uses a global network of edge locations to cache content closer to users. Option A (incorrect) Amazon EC2 provides virtual servers in the cloud. While applications can run on EC2, it does not inherently provide global content caching at edge locations to reduce latency for end-users. Option C (incorrect) Amazon S3 is object storage that can host static content, but it does not automatically distribute and cache content at edge locations worldwide. It typically serves as the origin for CloudFront. Option D (incorrect) AWS Direct Connect provides a dedicated private connection between a customer''s on-premises data center and AWS, which is used for hybrid cloud scenarios, not for global content delivery to end-users over the internet.', 62, 'm_62_2', 6, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_7
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A marketing department needs to analyze customer feedback from various text sources, such as emails, social media posts, and support tickets, to identify sentiment and key phrases. They want to use a fully managed service that requires no machine learning expertise. Which AWS service should they use?', '["Amazon SageMaker","Amazon Comprehend","Amazon Rekognition","Amazon EMR"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon Comprehend is a natural language processing (NLP) service that uses machine learning to find insights and relationships in text. It can identify sentiment, key phrases, entities, and more, without requiring any ML expertise, making it ideal for analyzing customer feedback. Option A (incorrect) Amazon SageMaker is a fully managed service that enables developers and data scientists to build, train, and deploy machine learning models at scale. It requires ML expertise to develop custom models, which the marketing department explicitly wants to avoid. Option C (incorrect) Amazon Rekognition is an image and video analysis service that can identify objects, people, text, and activities. It is not designed for text analysis. Option D (incorrect) Amazon EMR is a big data processing service that allows running frameworks like Hadoop and Spark. While it can be used for complex data analysis, it requires significant operational and data engineering expertise and is not a pre-built AI service for text analysis.', 62, 'm_62_7', 7, NULL, NULL),
  ('mock_60_all_1775000080858', 'A data analytics team frequently performs ad-hoc SQL queries on large datasets stored in Amazon S3 for business intelligence purposes. They want a serverless solution that allows them to query data directly without provisioning or managing any infrastructure, to minimize operational overhead. Which AWS service meets this requirement?', '["Amazon RDS","Amazon Redshift","Amazon Athena","Amazon EMR"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon Athena is a serverless interactive query service that makes it easy to analyze data directly in Amazon S3 using standard SQL. It eliminates the need to provision, manage, or scale any infrastructure, aligning perfectly with the requirement for minimal operational overhead for ad-hoc queries. Option A (incorrect) Amazon RDS is a managed relational database service. While it supports SQL, it requires provisioning and managing database instances, which introduces operational overhead and is not designed for querying large datasets directly from S3. Option B (incorrect) Amazon Redshift is a fully managed, petabyte-scale data warehousing service. It is optimized for complex analytical queries but requires provisioning and managing a cluster, which is not serverless and incurs more operational overhead than Athena for ad-hoc S3 queries. Option D (incorrect) Amazon EMR is a big data platform for processing vast amounts of data using frameworks like Hadoop and Spark. It requires managing clusters and is not a serverless solution for direct SQL queries on S3.', 62, 'm_62_7', 8, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company needs to create interactive dashboards and visualizations from various AWS data sources, including Amazon S3 and Amazon RDS, to provide business insights to non-technical users. They are looking for a fully managed, serverless business intelligence (BI) service that can scale automatically. Which AWS service should they use?', '["Amazon QuickSight","AWS Glue","Amazon Kinesis","Amazon SageMaker"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) Amazon QuickSight is a scalable, serverless, cloud-powered business intelligence (BI) service that makes it easy to create and publish interactive dashboards. It integrates with various AWS data sources and is designed for non-technical users to gain insights without managing any servers. Option B (incorrect) AWS Glue is a serverless data integration service that makes it easy to discover, prepare, and combine data for analytics, machine learning, and application development. While it prepares data, it does not provide dashboarding or visualization capabilities. Option C (incorrect) Amazon Kinesis is a service for processing large streams of data in real time. It is used for data ingestion and processing, not for creating interactive dashboards. Option D (incorrect) Amazon SageMaker is a machine learning service for building, training, and deploying ML models. It is not a BI service for creating dashboards.', 62, 'm_62_7', 9, NULL, NULL),
  ('mock_60_all_1775000080858', 'A media company needs to process large volumes of video files stored in Amazon S3. They want to automatically detect objects, scenes, and activities within these videos without developing custom machine learning models. Which AWS service provides pre-trained AI capabilities for video analysis?', '["Amazon SageMaker","Amazon Comprehend","Amazon Rekognition","AWS Glue"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon Rekognition is a fully managed artificial intelligence service that provides image and video analysis capabilities. It can detect objects, scenes, activities, faces, and text in images and videos using pre-trained models, eliminating the need for custom ML development. Option A (incorrect) Amazon SageMaker is a service for building, training, and deploying custom machine learning models. It requires ML expertise and is not a pre-trained AI service for direct video analysis. Option B (incorrect) Amazon Comprehend is a natural language processing (NLP) service for analyzing text. It is not designed for video analysis. Option D (incorrect) AWS Glue is a serverless data integration service for ETL (Extract, Transform, Load) operations. It is used for data preparation and movement, not for AI-powered video content analysis.', 62, 'm_62_7', 10, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company wants to collect and process real-time clickstream data from its website to analyze user behavior and personalize experiences. They need a service that can ingest and process large streams of data with low latency. Which AWS service is designed for real-time data streaming?', '["AWS Glue","Amazon Kinesis","Amazon S3","Amazon Redshift"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon Kinesis is a platform for streaming data on AWS, offering services to load and analyze streaming data. Amazon Kinesis Data Streams can continuously capture and store gigabytes of data per second from hundreds of thousands of sources, making it ideal for real-time clickstream analysis with low latency. Option A (incorrect) AWS Glue is a serverless data integration service for ETL (Extract, Transform, Load) operations. While it can process data, it is typically used for batch processing or preparing data for analytics, not for real-time ingestion and processing of data streams. Option C (incorrect) Amazon S3 is object storage and can store large volumes of data, but it is not designed for real-time data ingestion and processing of streaming data. Data is typically written to S3 in batches or as objects. Option D (incorrect) Amazon Redshift is a data warehousing service optimized for analytical queries on large datasets. It is not designed for real-time data ingestion and stream processing.', 62, 'm_62_7', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is developing a new application that experiences unpredictable traffic patterns, with usage spiking significantly during certain hours and remaining low otherwise. They want to ensure their application can automatically scale compute capacity up and down to match demand, while minimizing costs for idle resources. Which AWS compute service and scaling feature combination is MOST appropriate?', '["Amazon EC2 with Reserved Instances","AWS Lambda with Auto Scaling","Amazon EC2 with Auto Scaling","Amazon Lightsail with fixed plans"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon EC2 with Auto Scaling allows the application to automatically adjust the number of EC2 instances based on demand, ensuring performance during peak times and reducing costs during low usage by scaling down. This directly addresses unpredictable traffic and cost optimization. Option A (incorrect) Amazon EC2 with Reserved Instances provides significant cost savings for instances with steady-state usage, but it does not automatically scale capacity up and down to match unpredictable demand, potentially leading to over-provisioning or under-provisioning. Option B (incorrect) AWS Lambda is a serverless compute service that automatically scales with demand and charges per invocation, making it highly cost-effective for sporadic workloads. However, the question implies a traditional application that benefits from EC2''s flexibility and the combination of EC2 with Auto Scaling is a direct and common solution for this scenario. While Lambda is serverless and scales, EC2 with Auto Scaling is a more direct answer for scaling ''compute capacity'' in a general application context, especially if it''s not purely event-driven functions. Option D (incorrect) Amazon Lightsail offers fixed-size virtual private servers with predictable pricing. It does not provide automatic scaling capabilities to handle unpredictable traffic patterns effectively.', 62, 'm_62_3', 12, NULL, NULL),
  ('mock_60_all_1775000080858', 'A media streaming service anticipates massive, sudden spikes in user traffic during live events, requiring its backend application to handle millions of concurrent requests. They need a compute solution that can automatically distribute incoming application traffic across multiple targets, such as Amazon EC2 instances, and ensure high availability. Which AWS service is essential for this requirement?', '["Amazon EC2 Auto Scaling","Elastic Load Balancing (ELB)","AWS Lambda","Amazon ECS"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Elastic Load Balancing (ELB) automatically distributes incoming application traffic across multiple targets, such as Amazon EC2 instances, in multiple Availability Zones. This ensures high availability and fault tolerance, and it is crucial for handling sudden spikes in traffic by efficiently spreading the load. Option A (incorrect) Amazon EC2 Auto Scaling automatically adjusts the number of EC2 instances in response to demand. While essential for handling traffic spikes, it works in conjunction with ELB, which is responsible for distributing the traffic itself. Auto Scaling scales the capacity, ELB distributes the traffic. Option C (incorrect) AWS Lambda is a serverless compute service for running code without provisioning or managing servers. While it scales automatically, it is typically used for event-driven functions and not for distributing traffic to a fleet of traditional application servers. Option D (incorrect) Amazon ECS (Elastic Container Service) is a fully managed container orchestration service. While it manages containers, it still relies on an Elastic Load Balancer to distribute traffic to the running containers.', 62, 'm_62_3', 13, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is modernizing its application architecture and wants to deploy containerized applications without having to provision, manage, or scale the underlying Amazon EC2 instances that host the containers. They prioritize minimizing operational overhead for container infrastructure. Which AWS service should they choose?', '["Amazon EC2","Amazon ECS on EC2 launch type","AWS Fargate","Amazon Lightsail"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) AWS Fargate is a serverless compute engine for Amazon ECS and Amazon EKS that allows you to run containers without having to provision, manage, or scale the underlying EC2 instances. This significantly reduces operational overhead by abstracting away the server infrastructure. Option A (incorrect) Amazon EC2 requires users to provision, manage, and scale virtual servers, including operating system patching and maintenance, which is contrary to the goal of minimizing operational overhead for container infrastructure. Option B (incorrect) Amazon ECS on EC2 launch type still requires managing the EC2 instances that serve as container hosts, even though ECS orchestrates the containers. This does not fully eliminate the operational overhead of server management. Option D (incorrect) Amazon Lightsail provides simple virtual private servers and managed databases. It is not designed for serverless container deployment and still requires managing the virtual server.', 62, 'm_62_3', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A social media application needs a database that can handle millions of requests per second with single-digit millisecond latency. The application''s data model is highly flexible, requiring a schema-less design to store user profiles and activity feeds that can vary significantly. Which AWS database service is BEST suited for these requirements?', '["Amazon RDS for MySQL","Amazon Aurora PostgreSQL-Compatible Edition","Amazon DynamoDB","Amazon Redshift"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon DynamoDB is a fully managed NoSQL (key-value and document) database service that delivers single-digit millisecond performance at any scale. Its schema-less design and flexible data model are ideal for applications with highly variable data, such as user profiles and activity feeds in a social media application. Option A (incorrect) Amazon RDS for MySQL is a managed relational database service. Relational databases enforce rigid schemas and are generally not optimized for the extreme scale and flexible data models required by this scenario, nor do they typically offer single-digit millisecond latency at millions of requests per second. Option B (incorrect) Amazon Aurora PostgreSQL-Compatible Edition is a high-performance relational database. While it offers better performance than standard RDS, it still adheres to a relational model and is not designed for the schema flexibility and extreme scale of a NoSQL database like DynamoDB. Option D (incorrect) Amazon Redshift is a fully managed, petabyte-scale data warehousing service optimized for analytical queries. It is not designed for high-throughput transactional workloads with flexible schemas.', 62, 'm_62_4', 15, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is migrating its existing on-premises relational database to AWS. They want to offload operational tasks such as hardware provisioning, database setup, patching, and backups to AWS, while still having full control over database parameters and access. Which AWS database service should they choose?', '["Amazon EC2 with self-managed MySQL","Amazon RDS","Amazon DynamoDB","Amazon Redshift"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon RDS (Relational Database Service) is a fully managed relational database service that automates administrative tasks like hardware provisioning, database setup, patching, and backups. It supports various database engines, including MySQL, and allows users to retain control over database parameters and access, making it ideal for migrating existing relational databases. Option A (incorrect) running a self-managed MySQL database on Amazon EC2 requires the user to handle all operational tasks, including OS management, patching, backups, and high availability, which is contrary to the goal of offloading operational overhead. Option C (incorrect) Amazon DynamoDB is a NoSQL database service. While fully managed, it is not suitable for migrating existing relational databases that require a SQL interface and relational schema. Option D (incorrect) Amazon Redshift is a data warehousing service optimized for analytics. It is not designed for transactional workloads or as a direct replacement for an operational relational database.', 62, 'm_62_4', 16, NULL, NULL),
  ('mock_60_all_1775000080858', 'A web application experiences heavy read traffic, causing performance bottlenecks on its primary Amazon RDS database. The development team wants to improve read performance and reduce the load on the primary database without significantly re-architecting the application. Which AWS service can help offload read requests and provide microsecond-latency caching?', '["Amazon DynamoDB","Amazon ElastiCache","Amazon Redshift","Amazon S3"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon ElastiCache is a fully managed in-memory caching service that supports Redis and Memcached. It can significantly improve application performance by offloading read-heavy workloads from the primary database and providing microsecond-latency data retrieval for frequently accessed data. Option A (incorrect) Amazon DynamoDB is a NoSQL database service, not an in-memory caching solution for relational databases. It would require a significant re-architecture to use as a primary data store. Option C (incorrect) Amazon Redshift is a data warehousing service for analytics, not for caching or offloading transactional read traffic from an operational database. Option D (incorrect) Amazon S3 is object storage and is not designed for high-performance, low-latency caching of database query results.', 62, 'm_62_4', 17, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company needs to host its internal application servers and databases in a private network segment within AWS, ensuring they are not directly accessible from the internet. However, these resources still need to initiate outbound connections to download updates and access third-party APIs. Which VPC component should be used to enable outbound internet access for private subnets?', '["Internet Gateway","Security Group","NAT Gateway","VPC Peering"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) a NAT Gateway (Network Address Translation Gateway) allows instances in a private subnet to connect to the internet or other AWS services, but it prevents the internet from initiating connections to those instances. This meets the requirement for outbound-only internet access for resources in private subnets. Option A (incorrect) an Internet Gateway allows resources in a public subnet to connect to the internet and allows inbound internet traffic. Placing application servers and databases in a public subnet with an Internet Gateway would expose them directly to the internet, violating the privacy requirement. Option B (incorrect) a Security Group acts as a virtual firewall for instances to control inbound and outbound traffic at the instance level. While essential for security, it does not provide the mechanism for private subnets to access the internet. Option D (incorrect) VPC Peering connects two VPCs, allowing resources in one VPC to communicate with resources in the other as if they were in the same network. It does not provide internet access for private subnets.', 62, 'm_62_5', 18, NULL, NULL),
  ('mock_60_all_1775000080858', 'A security team needs to implement a stateless firewall at the subnet level within an Amazon VPC to control traffic entering and leaving specific subnets. They require rules for both inbound and outbound traffic, and these rules should be evaluated in order. Which AWS networking component should they configure?', '["Security Group","Network Access Control List (NACL)","VPC Flow Logs","AWS WAF"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) a Network Access Control List (NACL) is a stateless firewall that operates at the subnet level. It allows or denies traffic based on rules, which are evaluated in order, and requires explicit rules for both inbound and outbound traffic. This perfectly matches the requirement for a stateless, subnet-level firewall. Option A (incorrect) a Security Group is a stateful firewall that operates at the instance level. It automatically allows return traffic for any allowed inbound or outbound connection, and rules are not evaluated in order. This does not meet the ''stateless'' and ''subnet-level'' requirements. Option C (incorrect) VPC Flow Logs capture information about the IP traffic going to and from network interfaces in a VPC. They are used for monitoring and troubleshooting, not for controlling traffic. Option D (incorrect) AWS WAF (Web Application Firewall) helps protect web applications from common web exploits. It operates at the application layer (Layer 7) and is not a subnet-level firewall.', 62, 'm_62_5', 19, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company hosts a public-facing web application on Amazon EC2 instances behind an Elastic Load Balancer. They need to ensure that users can access the application using a custom domain name (e.g., www.example.com) and that traffic is routed efficiently to the healthy instances. Which AWS service is primarily responsible for managing domain names and routing internet traffic to the application?', '["Amazon VPC","Amazon CloudFront","Amazon Route 53","AWS Direct Connect"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon Route 53 is a highly available and scalable cloud Domain Name System (DNS) web service. It can register domain names and route internet traffic to resources such as Amazon EC2 instances or Elastic Load Balancers, often using health checks to ensure traffic is directed only to healthy endpoints. Option A (incorrect) Amazon VPC (Virtual Private Cloud) allows you to provision a logically isolated section of the AWS Cloud where you can launch AWS resources in a virtual network that you define. It defines the network environment but does not manage public domain names or route internet traffic from outside the VPC. Option B (incorrect) Amazon CloudFront is a content delivery network (CDN) service that speeds up the delivery of web content to users. While it can use custom domains, its primary function is content caching and distribution, not core DNS resolution for the application''s origin. Option D (incorrect) AWS Direct Connect establishes a dedicated private network connection between a customer''s on-premises data center and AWS. It is not used for public domain name management or routing internet traffic to public web applications.', 62, 'm_62_5', 20, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_6
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company needs to store large archives of historical data that are rarely accessed (less than once a year) but must be retained for compliance reasons for several years. They prioritize the LOWEST possible storage cost. Which Amazon S3 storage class is MOST appropriate for this use case?', '["Amazon S3 Standard","Amazon S3 Standard-Infrequent Access (S3 Standard-IA)","Amazon S3 One Zone-Infrequent Access (S3 One Zone-IA)","Amazon S3 Glacier Deep Archive"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) Amazon S3 Glacier Deep Archive is the lowest-cost storage class for archival data that is accessed rarely, typically once or twice a year, and can tolerate retrieval times of several hours. This perfectly matches the requirement for the lowest possible storage cost for rarely accessed historical data. Option A (incorrect) Amazon S3 Standard is designed for frequently accessed data and is the most expensive S3 storage class, making it unsuitable for rarely accessed archives. Option B (incorrect) Amazon S3 Standard-Infrequent Access (S3 Standard-IA) is for data that is accessed less frequently but requires rapid access when needed. It is more cost-effective than S3 Standard but significantly more expensive than Glacier Deep Archive for data accessed less than once a year. Option C (incorrect) Amazon S3 One Zone-Infrequent Access (S3 One Zone-IA) is similar to S3 Standard-IA but stores data in a single Availability Zone, offering lower cost but less durability and availability. It is still not the lowest cost option for deep archives.', 62, 'm_62_6', 21, NULL, NULL),
  ('mock_60_all_1775000080858', 'A team of data scientists needs a shared file system that can be mounted by multiple Amazon EC2 instances simultaneously. This file system will store large datasets and scripts that need to be accessed and modified concurrently by different compute instances for their analysis workloads. Which AWS storage service should they use?', '["Amazon EBS General Purpose SSD (gp3) volume","Amazon S3 Standard","Amazon EFS","Amazon FSx for Windows File Server"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon EFS (Elastic File System) provides a scalable, elastic, cloud-native NFS file system that can be mounted by thousands of Amazon EC2 instances simultaneously. It is designed for shared file access across multiple instances, making it ideal for data science workloads where multiple compute instances need to access and modify the same datasets concurrently. Option A (incorrect) an Amazon EBS (Elastic Block Store) volume can typically only be attached to a single EC2 instance at a time (with the exception of Multi-Attach for io1/io2 volumes, which is not the general use case for shared file systems). It is block storage, not a shared file system. Option B (incorrect) Amazon S3 Standard is object storage. While it can store large datasets, it is not a file system that can be mounted by EC2 instances and does not support concurrent file-level access and modification in the same way EFS does. Option D (incorrect) Amazon FSx for Windows File Server provides a fully managed native Microsoft Windows file system. While it is a shared file system, EFS is generally the more common and flexible choice for Linux-based data science workloads requiring NFS access across many instances.', 62, 'm_62_6', 22, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company needs to migrate 500 terabytes of archival data from its on-premises data center to Amazon S3. Their internet connection has limited bandwidth, and transferring this amount of data over the network would take several weeks, impacting their migration timeline. Which AWS service can accelerate this large-scale data transfer?', '["AWS Storage Gateway","AWS DataSync","AWS Snowball","Amazon S3 Transfer Acceleration"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) AWS Snowball is a petabyte-scale data transfer device that allows you to securely and quickly transfer large amounts of data into and out of AWS. For 500 terabytes, physically shipping a Snowball device is significantly faster and more cost-effective than transferring over a limited internet connection. Option A (incorrect) AWS Storage Gateway connects an on-premises software appliance with cloud-based storage to provide seamless integration, but it relies on existing network connectivity and is not designed for large-scale offline data migration. Option B (incorrect) AWS DataSync is an online data transfer service that simplifies, automates, and accelerates moving data between on-premises storage and AWS storage services over the network. While it accelerates online transfers, it still depends on network bandwidth and is not suitable for petabyte-scale transfers with severely limited internet connectivity. Option D (incorrect) Amazon S3 Transfer Acceleration speeds up long-distance transfers of files to and from an S3 bucket over the internet, but it is still limited by the available internet bandwidth and is not designed for petabyte-scale transfers that would take weeks.', 62, 'm_62_6', 23, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_8
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A mobile application needs to send push notifications to millions of users when new content is available. The solution must be highly scalable, reliable, and capable of delivering messages to various endpoint types (e.g., iOS, Android, SMS). Which AWS service is best suited for this mass notification requirement?', '["Amazon SQS","Amazon SNS","AWS Step Functions","Amazon EventBridge"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) Amazon SNS (Simple Notification Service) is a highly available, durable, secure, fully managed pub/sub messaging service that enables you to decouple microservices, distributed systems, and serverless applications. It can deliver messages to a large number of subscribers and various endpoint types, including mobile push notifications, SMS, email, and AWS Lambda functions, making it ideal for mass notifications. Option A (incorrect) Amazon SQS (Simple Queue Service) is a message queuing service used for decoupling and scaling microservices, distributed systems, and serverless applications. While reliable, it is a pull-based model (consumers retrieve messages from a queue) and is not designed for broadcasting messages to multiple subscribers or push notifications. Option C (incorrect) AWS Step Functions is a serverless workflow service that lets you combine AWS Lambda functions and other AWS services to build business-critical applications. It is for orchestrating workflows, not for mass notifications. Option D (incorrect) Amazon EventBridge is a serverless event bus service that makes it easier to connect applications together using data from your own applications, integrated SaaS applications, and AWS services. While it handles events, SNS is specifically designed for the broader use case of mass notifications and fan-out messaging.', 62, 'm_62_8', 24, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company needs to ensure that all its AWS resources, including Amazon EC2 instances, Amazon RDS databases, and Amazon S3 buckets, are regularly backed up according to a centralized policy. They want a fully managed service that simplifies backup management and compliance across multiple AWS services. Which AWS service provides a centralized backup solution?', '["AWS Backup","Amazon S3 Versioning","Amazon EBS Snapshots","Amazon RDS Automated Backups"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) AWS Backup is a fully managed, centralized backup service that makes it easy to back up your data across AWS services in the cloud and on premises. It allows you to configure backup policies, schedule backups, and manage retention periods for various AWS resources from a single console. Option B (incorrect) Amazon S3 Versioning helps protect objects in an S3 bucket from accidental deletion or overwrites by keeping multiple versions of an object. It is specific to S3 and not a centralized backup solution for other AWS services. Option C (incorrect) Amazon EBS Snapshots are point-in-time backups of EBS volumes. While essential for EC2 data protection, they are specific to EBS and do not provide a centralized backup solution for other services. Option D (incorrect) Amazon RDS Automated Backups are specific to Amazon RDS databases and provide point-in-time recovery. They do not offer centralized backup management for other AWS resources.', 62, 'm_62_8', 25, NULL, NULL),
  ('mock_60_all_1775000080858', 'A development team wants to quickly deploy a simple web application without manually configuring servers, databases, or load balancers. They need a service that provides an easy-to-use interface for launching and managing pre-configured virtual private servers, databases, and other application components. Which AWS service is designed for this simplified approach?', '["Amazon EC2","AWS Lambda","Amazon Lightsail","AWS CloudFormation"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) Amazon Lightsail is designed for users who need to launch and manage simple web applications or websites quickly. It offers pre-configured bundles that include a virtual private server (VPS), SSD-based storage, data transfer, DNS management, and a static IP, simplifying the deployment process significantly compared to other services. Option A (incorrect) Amazon EC2 provides raw virtual servers, requiring users to configure the operating system, install software, and manage networking and scaling manually, which is not a simplified approach. Option B (incorrect) AWS Lambda is a serverless compute service for running code in response to events. It is not designed for hosting traditional web applications with a full server stack and database in a simplified bundle. Option D (incorrect) AWS CloudFormation is an Infrastructure as Code service for defining and provisioning AWS resources. While it automates infrastructure setup, it requires writing templates and is not an ''easy-to-use interface for launching and managing pre-configured virtual private servers'' for simple applications.', 62, 'm_62_8', 26, NULL, NULL);

