INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A startup is deploying a new web application on Amazon EC2 instances. The application is expected to have a consistent, predictable workload running 24/7 for the next three years. The finance team requires the MOST cost-effective solution for this long-term, steady-state compute requirement.', '["Purchase Amazon EC2 Reserved Instances for a 3-year term.","Utilize Amazon EC2 On-Demand Instances to maintain flexibility.","Implement Amazon EC2 Spot Instances for significant cost savings.","Use AWS Lambda for the application to pay only for compute time."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most cost-effective solution for a consistent, predictable workload running 24/7 for a long term. Reserved Instances offer significant discounts (up to 72%) compared to On-Demand pricing in exchange for a 1-year or 3-year commitment. Option B (incorrect) would be the most expensive option for a steady-state workload, as On-Demand pricing offers no discounts for long-term commitment, violating the ''MOST cost-effective'' constraint. Option C (incorrect) is not suitable for a production web application requiring continuous availability, as Spot Instances can be interrupted with short notice, making them ideal for fault-tolerant or flexible workloads, not steady-state production. Option D (incorrect) is a serverless compute service, but the scenario explicitly mentions Amazon EC2 instances and the need for a consistent, predictable workload, implying a traditional server-based application where Reserved Instances are applicable for cost optimization.', 63, 'm_63_1', 1, NULL, NULL),
  ('mock_60_all_1775000080858', 'A data analytics company needs to process large datasets using Amazon EC2 instances. These processing jobs are fault-tolerant, can be interrupted, and can resume from a checkpoint. The company''s primary goal is to minimize compute costs for these non-critical, flexible workloads.', '["Provision Amazon EC2 On-Demand Instances to ensure job completion without interruption.","Utilize Amazon EC2 Spot Instances, bidding on unused capacity for significant discounts.","Purchase Amazon EC2 Reserved Instances for a 1-year term to get a discount.","Use AWS Lambda functions for processing to achieve a serverless, cost-effective solution."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective solution for fault-tolerant, interruptible workloads. Amazon EC2 Spot Instances allow users to bid on unused EC2 capacity, offering discounts of up to 90% compared to On-Demand pricing. Since the jobs can tolerate interruption and resume, Spot Instances are ideal. Option A (incorrect) would be significantly more expensive than Spot Instances for this type of workload, as On-Demand instances are priced at the full rate. Option C (incorrect) is designed for steady-state, predictable workloads and requires a commitment, which is not suitable for interruptible, flexible jobs. Option D (incorrect) might be suitable for some data processing, but the scenario specifically mentions using Amazon EC2 instances for large datasets, implying a need for dedicated compute capacity that might exceed Lambda''s typical use cases or execution limits for long-running batch jobs.', 63, 'm_63_1', 2, NULL, NULL),
  ('mock_60_all_1775000080858', 'A media company stores petabytes of video archives in Amazon S3. They need to understand the primary factors that contribute to their monthly Amazon S3 bill to optimize costs. Which of the following are the main components of Amazon S3 pricing?', '["Number of Amazon S3 buckets and data transfer IN to Amazon S3.","Amazon S3 instance hours and data processing fees.","Storage used, data transfer OUT from Amazon S3, and requests made.","Amazon S3 compute capacity and provisioned IOPS."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) accurately describes the main components of Amazon S3 pricing. Customers are primarily charged for the amount of data stored (storage used), data transferred out of Amazon S3 to other AWS Regions or the internet (data transfer OUT), and the number and type of requests made to their S3 buckets (requests made). Option A (incorrect) states data transfer IN, which is generally free for Amazon S3, and the number of buckets is not a primary pricing factor. Option B (incorrect) mentions ''Amazon S3 instance hours'' and ''data processing fees,'' which are not terms used in Amazon S3 pricing; instance hours relate to EC2, and S3 charges for requests, not general processing. Option D (incorrect) refers to ''Amazon S3 compute capacity'' and ''provisioned IOPS,'' which are concepts related to compute services like Amazon EC2 or database services like Amazon EBS, not Amazon S3.', 63, 'm_63_1', 3, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is designing a new application that will frequently transfer large amounts of data between an Amazon EC2 instance in us-east-1 and an Amazon S3 bucket in eu-west-1. They are concerned about potential costs associated with data movement. Which statement accurately describes AWS data transfer pricing?', '["All data transfer into AWS Regions is charged, while data transfer out is free.","Data transfer between AWS services within the same AWS Region is always free.","Data transfer out of AWS Regions to the internet and between different AWS Regions is charged.","Data transfer between an Amazon EC2 instance and an Amazon S3 bucket, regardless of Region, is always free."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) accurately describes AWS data transfer pricing. Data transfer out of AWS Regions to the internet and data transfer between different AWS Regions are generally charged. This includes the scenario described where data moves between us-east-1 and eu-west-1. Option A (incorrect) is the opposite of how AWS typically charges; data transfer IN to AWS is generally free, while data transfer OUT is charged. Option B (incorrect) is partially true, but not ''always free'' for all services; while often free within the same Availability Zone, cross-Availability Zone data transfer within the same Region can incur charges. Option D (incorrect) is incorrect because data transfer between an Amazon EC2 instance and an Amazon S3 bucket in different AWS Regions will incur cross-Region data transfer charges, which is a common misconception (ap-4.1-004).', 63, 'm_63_1', 4, NULL, NULL),
  ('mock_60_all_1775000080858', 'A development team needs to spin up several Amazon EC2 instances for a short-term project expected to last a few weeks. The workload is unpredictable, with varying compute demands throughout the day. The team prioritizes flexibility and wants to avoid any long-term commitments. Which pricing model is MOST appropriate for this scenario?', '["Amazon EC2 On-Demand Instances.","Amazon EC2 Reserved Instances.","Amazon EC2 Savings Plans.","Amazon EC2 Dedicated Hosts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most appropriate pricing model for short-term, unpredictable workloads without long-term commitments. On-Demand Instances allow users to pay for compute capacity by the second or hour with no upfront costs or minimum commitments, providing maximum flexibility. Option B (incorrect) requires a 1-year or 3-year commitment and is best suited for steady-state, predictable workloads, making it unsuitable for a short-term, unpredictable project (ap-4.1-003). Option C (incorrect) also requires a 1-year or 3-year commitment for a consistent amount of compute usage, similar to Reserved Instances, and is not ideal for short-term, unpredictable needs. Option D (incorrect) provides dedicated physical EC2 servers for specific compliance or licensing requirements and is a much more expensive option not relevant to cost-effective, short-term flexibility.', 63, 'm_63_1', 5, NULL, NULL),
  ('mock_60_all_1775000080858', 'A new developer is exploring AWS services for the first time and wants to experiment with Amazon EC2, Amazon S3, and AWS Lambda without incurring unexpected costs. What is the BEST approach for this developer to get started with these services at no charge?', '["Sign up for a Developer Support plan to get free usage credits.","Utilize the AWS Free Tier, which offers limited free usage for new accounts.","Purchase a 1-year Amazon EC2 Reserved Instance and use the free S3 storage.","Start with On-Demand instances and manually monitor costs with AWS Cost Explorer."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the best approach for a new developer to experiment with AWS services at no charge. The AWS Free Tier provides a certain amount of free usage for many services, including Amazon EC2 (e.g., 750 hours/month of t2.micro), Amazon S3 (e.g., 5 GB standard storage), and AWS Lambda (e.g., 1 million free requests), for 12 months for new accounts. Option A (incorrect) is an AWS Support plan that provides technical assistance but does not include free usage credits for general experimentation. Option C (incorrect) involves a long-term financial commitment for Reserved Instances and does not cover the breadth of free experimentation across multiple services, nor does it align with a ''no charge'' starting point. Option D (incorrect) would incur costs immediately for On-Demand instances and relies on reactive monitoring, which contradicts the goal of avoiding costs during initial experimentation (ap-4.1-001).', 63, 'm_63_1', 6, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_63_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A company is migrating its critical production application to AWS. The application requires 24/7 technical support, fast response times for critical issues, and proactive guidance on best practices. Which AWS Support plan should the company choose to meet these requirements?', '["Basic Support, as it is free and provides access to documentation.","Developer Support, offering email support during business hours.","Business Support, providing 24/7 phone, chat, and email access with faster response times.","AWS re:Post, which is a community forum for technical questions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the appropriate AWS Support plan for a critical production application. Business Support provides 24/7 access to Cloud Support Engineers via phone, chat, and email, with faster response times for critical issues (e.g., 1 hour for production system impaired, 15 minutes for production system down). It also includes access to AWS Trusted Advisor''s full set of checks. Option A (incorrect) is free but offers no technical support, only customer service for billing and account issues, making it unsuitable for a production workload (ap-4.3-001). Option B (incorrect) offers technical support via email during business hours, which is insufficient for a critical 24/7 production application requiring fast response times. Option D (incorrect) is a community-driven Q&A forum and not an official AWS Support plan for direct technical assistance.', 63, 'm_63_3', 7, NULL, NULL),
  ('mock_60_all_1775000080858', 'A solutions architect wants to proactively identify potential cost savings, security vulnerabilities, and performance improvements across their AWS environment. They need an automated service that provides recommendations based on AWS best practices. Which AWS service should the architect use?', '["AWS Health Dashboard to monitor service events.","AWS Billing Dashboard to review monthly charges.","AWS Trusted Advisor to provide best practice recommendations.","AWS Cost Explorer to visualize spending patterns."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the service designed to proactively identify potential cost savings, security vulnerabilities, performance improvements, fault tolerance, and service limit recommendations based on AWS best practices. AWS Trusted Advisor provides a dashboard of checks and actionable advice. Option A (incorrect) provides personalized alerts about AWS service events that may affect your resources, but it does not offer proactive recommendations for cost, security, or performance improvements. Option B (incorrect) provides an overview of your monthly AWS charges and payment history but does not offer recommendations for optimization. Option D (incorrect) is used for visualizing and analyzing historical and forecasted spending patterns, not for identifying best practice recommendations across multiple pillars (ap-4.3-002).', 63, 'm_63_3', 8, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company operates several critical applications on AWS. The operations team needs a centralized view of the health and performance of the AWS services they are using, along with personalized notifications about service events that might impact their specific resources. Which AWS service provides this capability?', '["AWS Health Dashboard.","AWS Trusted Advisor.","AWS Cost Explorer.","AWS Billing Dashboard."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the service that provides a personalized view of the health of AWS services and alerts about service events that might impact your specific AWS resources. It helps users stay informed about outages, scheduled maintenance, and other operational events. Option B (incorrect) provides recommendations for cost optimization, security, performance, and fault tolerance, but it does not provide real-time, personalized service health notifications. Option C (incorrect) is used for visualizing and analyzing AWS spending patterns. Option D (incorrect) provides an overview of your AWS account''s billing information, not service health (ap-4.3-003).', 63, 'm_63_3', 9, NULL, NULL),
  ('mock_60_all_1775000080858', 'A large enterprise with a complex AWS environment requires a dedicated expert to provide proactive guidance, architectural reviews, and act as a primary point of contact for strategic AWS initiatives. Which AWS Support plan includes this level of personalized, high-touch assistance?', '["Basic Support.","Developer Support.","Enterprise Support.","Business Support."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Support plan that includes a dedicated Technical Account Manager (TAM) who provides proactive guidance, architectural reviews, and serves as a primary point of contact for strategic initiatives. This level of support is designed for large enterprises with complex needs. Option A (incorrect) is free and offers no technical support or TAM. Option B (incorrect) offers email support during business hours but does not include a TAM. Option D (incorrect) provides 24/7 technical support via phone, chat, and email and access to AWS Trusted Advisor, but it does not include a dedicated TAM (ap-4.3-005).', 63, 'm_63_3', 10, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company is looking for general guidance on designing and operating reliable, secure, efficient, and cost-effective workloads in the cloud. They want to understand AWS best practices across various pillars. Which AWS resource provides this foundational architectural guidance?', '["AWS Health Dashboard for operational event notifications.","AWS Cost Explorer for detailed cost analysis.","AWS documentation and whitepapers, such as the AWS Well-Architected Framework.","AWS Support plans for direct technical assistance."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) provides foundational architectural guidance and best practices. AWS documentation, particularly whitepapers like the AWS Well-Architected Framework, offers comprehensive principles and recommendations across pillars like Operational Excellence, Security, Reliability, Performance Efficiency, Cost Optimization, and Sustainability. Option A (incorrect) provides personalized alerts about AWS service events, not general architectural guidance. Option B (incorrect) is a tool for visualizing and analyzing AWS spending patterns. Option D (incorrect) provides various levels of technical assistance for specific issues, but the documentation and whitepapers are the primary source for broad architectural best practices.', 63, 'm_63_3', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_63_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775000080858', 'A finance department wants to prevent unexpected cloud overspend by receiving automatic notifications when their monthly AWS costs or usage exceed predefined thresholds. They need a service that can track actual spending against a set limit and alert relevant stakeholders. Which AWS service should they configure?', '["AWS Budgets.","AWS Cost Explorer.","AWS Billing Dashboard.","AWS Cost and Usage Report."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is specifically designed for setting custom cost and usage thresholds and receiving alerts when actual or forecasted costs exceed those thresholds. This allows organizations to proactively manage their spending and prevent unexpected overruns. Option B (incorrect) is used for visualizing and analyzing historical and forecasted spending patterns, but it does not send proactive alerts based on custom thresholds. Option C (incorrect) provides an overview of the current month''s charges and payment history but lacks the proactive alerting capabilities. Option D (incorrect) provides highly detailed, line-item billing data, which is useful for deep analysis but not for real-time threshold-based alerting (ap-4.2-001).', 63, 'm_63_2', 12, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company has multiple departments using the same AWS account, and they need to track cloud costs by individual department and project. They want to easily allocate expenses to the correct cost centers for internal chargebacks and financial reporting. What AWS feature should they implement?', '["Use AWS Cost Explorer to manually categorize costs.","Implement cost allocation tags on their AWS resources.","Set up separate AWS accounts for each department.","Review the AWS Billing Dashboard for aggregated costs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most effective way to track costs by individual department and project within a single AWS account. Cost allocation tags are labels that users can apply to AWS resources (e.g., EC2 instances, S3 buckets) to categorize costs. These tags then appear on the AWS Cost and Usage Report and in AWS Cost Explorer, enabling granular cost tracking and reporting. Option A (incorrect) would be a manual and inefficient process for categorizing costs, especially at scale. Option C (incorrect) is a valid strategy for strong isolation but might be overkill if the primary need is just cost tracking, and it would still benefit from tags within each account. Option D (incorrect) provides an aggregated view of costs but does not offer the granular breakdown by department or project needed for internal chargebacks without additional tagging (ap-4.2-002).', 63, 'm_63_2', 13, NULL, NULL),
  ('mock_60_all_1775000080858', 'A financial analyst needs to understand the historical spending trends of their AWS account over the past year, identify the services driving the most cost, and forecast future expenses. Which AWS tool provides interactive graphs and customizable views for this type of analysis?', '["AWS Budgets for setting cost alerts.","AWS Cost and Usage Report for raw data.","AWS Cost Explorer for visualizing and analyzing spending patterns.","AWS Billing Dashboard for a high-level overview."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the primary tool for visualizing and analyzing historical AWS spending patterns, identifying cost drivers, and forecasting future costs. AWS Cost Explorer provides interactive graphs and customizable reports that allow users to drill down into their spending by service, region, tags, and more. Option A (incorrect) is used for setting cost and usage alerts, not for detailed historical analysis and visualization. Option B (incorrect) provides highly granular, line-item billing data, which is excellent for deep programmatic analysis but requires external tools or significant effort to visualize trends effectively. Option D (incorrect) offers a high-level summary of current charges but lacks the detailed analysis and forecasting capabilities of Cost Explorer (ap-4.2-003).', 63, 'm_63_2', 14, NULL, NULL),
  ('mock_60_all_1775000080858', 'A company''s accounting department requires a comprehensive, granular breakdown of all AWS services consumed, including detailed line items for every charge, usage type, and associated metadata. This report is needed for in-depth financial reconciliation and auditing. Which AWS resource provides this level of detail?', '["AWS Budgets.","AWS Cost Explorer.","AWS Cost and Usage Report (CUR).","AWS Billing Dashboard."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Cost and Usage Report (CUR), which provides the most comprehensive and granular data about your AWS costs and usage. It includes line items for every charge, usage type, and associated metadata, making it ideal for in-depth financial reconciliation, auditing, and custom cost analysis. Option A (incorrect) is used for setting cost and usage alerts, not for providing detailed billing data. Option B (incorrect) is used for visualizing and analyzing spending trends, but it aggregates data and does not provide the raw, line-item detail of the CUR. Option D (incorrect) offers a high-level overview of current charges and payment history, which is not sufficient for granular financial reconciliation.', 63, 'm_63_2', 15, NULL, NULL),
  ('mock_60_all_1775000080858', 'A large organization uses multiple AWS accounts for different departments and projects. They want to simplify billing, combine usage across accounts to qualify for volume discounts, and centralize cost management. Which AWS service should they use to achieve these goals?', '["AWS Organizations with consolidated billing.","AWS Cost Explorer for each individual account.","AWS Budgets configured separately for each account.","AWS Billing Dashboard to view individual account bills."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the service designed for managing multiple AWS accounts. AWS Organizations with consolidated billing allows an organization to consolidate billing for multiple AWS accounts into a single bill. This simplifies billing, enables volume discounts (as usage is aggregated across accounts), and centralizes cost management. Option B (incorrect) would require analyzing costs separately for each account, missing the benefit of consolidated billing and volume discounts. Option C (incorrect) would also require separate configuration and management for each account, not providing a centralized solution. Option D (incorrect) only shows individual account bills, not a consolidated view or the benefits of aggregated usage (ap-4.2-004).', 63, 'm_63_2', 16, NULL, NULL),
  ('mock_60_all_1775000080858', 'A new AWS account administrator needs to quickly view the current month''s charges, recent invoices, and payment history for their entire AWS account. They require a simple, high-level overview without needing to perform deep analysis. Which AWS resource should they access?', '["AWS Cost Explorer.","AWS Cost and Usage Report.","AWS Billing Dashboard.","AWS Budgets."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Billing Dashboard, which provides a high-level overview of your current month''s charges, recent invoices, and payment history. It''s designed for quick access to essential billing information without requiring detailed analysis. Option A (incorrect) is used for detailed visualization and analysis of historical and forecasted spending trends. Option B (incorrect) provides the most granular, line-item billing data for deep analysis, which is more than a ''simple, high-level overview''. Option D (incorrect) is used for setting custom cost and usage alerts, not for reviewing overall billing history.', 63, 'm_63_2', 17, NULL, NULL);

