INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A startup needs to launch a new e-commerce platform quickly, expecting unpredictable traffic spikes during promotional events. They want to minimize initial capital expenditure and only pay for resources as they are consumed, while ensuring the platform can handle sudden demand fluctuations. Which AWS Cloud benefit directly addresses these requirements?', '["Elasticity and pay-as-you-go pricing model.","Global infrastructure for low-latency access worldwide.","Dedicated hardware for consistent performance.","Reduced operational overhead through manual server management."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) directly addresses the requirements. Elasticity allows the platform to automatically scale capacity up or down to meet unpredictable traffic spikes, while the pay-as-you-go pricing model eliminates initial capital expenditure and ensures the company only pays for the resources consumed. Option B (incorrect) describes a benefit of global infrastructure, which is important for latency but doesn''t directly address capital expenditure or elastic scaling for unpredictable demand. Option C (incorrect) refers to dedicated hardware, which typically involves significant capital expenditure and contradicts the elasticity and pay-as-you-go model of the cloud. Option D (incorrect) suggests manual server management, which increases operational overhead, not reduces it, and does not align with the agility and elasticity benefits of AWS.', 60, 'm_60_1', 1, NULL, NULL),
  ('mock_60_all_1775002619521', 'A global media company wants to deliver video content to users across multiple continents with minimal latency. They need an infrastructure that can be deployed rapidly in various geographic locations without the need for physical data centers. Which AWS Cloud benefit is most relevant for this scenario?', '["Elimination of capacity planning by purchasing dedicated servers.","Benefits of global infrastructure, enabling deployment in minutes.","Reduced operational costs by performing manual software updates.","Focus on capital expenditure rather than operational expenditure."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) directly addresses the need for global content delivery with minimal latency and rapid deployment. AWS''s global infrastructure, comprising Regions and Availability Zones, allows companies to deploy applications close to their users worldwide in minutes. Option A (incorrect) suggests purchasing dedicated servers, which contradicts the elasticity and pay-as-you-go model of the cloud and doesn''t align with rapid global deployment. Option C (incorrect) refers to manual software updates, which increases operational overhead rather than reducing it, and is not a primary benefit for global low-latency content delivery. Option D (incorrect) focuses on capital expenditure, whereas a key benefit of the cloud is shifting from CapEx to OpEx, especially for global reach.', 60, 'm_60_1', 2, NULL, NULL),
  ('mock_60_all_1775002619521', 'A small software development firm is migrating its on-premises development and testing environments to the AWS Cloud. They want to reduce their overall IT spending by eliminating the need to purchase and maintain physical servers, while also gaining the flexibility to spin up and tear down environments as needed. Which economic benefit of AWS is primarily being leveraged here?', '["Increased capital expenditure for future hardware upgrades.","Fixed monthly costs regardless of resource usage.","Total Cost of Ownership (TCO) reduction through operational expenditure.","Maintaining existing on-premises licensing agreements without changes."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes the primary economic benefit. By moving to AWS, the firm reduces its Total Cost of Ownership (TCO) by eliminating capital expenditure (CapEx) on physical servers and shifting to operational expenditure (OpEx) where they pay only for what they use. This also provides the flexibility to spin up and tear down environments, further optimizing costs. Option A (incorrect) contradicts the goal of reducing capital expenditure. Option B (incorrect) is generally not true for cloud services, which are typically usage-based, not fixed monthly costs, especially for flexible dev/test environments. Option D (incorrect) might be a consideration for some migrations, but it doesn''t represent the primary economic benefit of eliminating physical server purchases and gaining flexibility.', 60, 'm_60_1', 3, NULL, NULL),
  ('mock_60_all_1775002619521', 'An enterprise is considering moving its critical business applications to the AWS Cloud. They are particularly concerned about ensuring their applications remain accessible even if an entire data center experiences an outage. Which AWS Cloud benefit directly addresses this concern?', '["The ability to deploy all resources within a single Availability Zone for simplicity.","Reduced need for security controls due to AWS''s shared responsibility model.","High availability and fault tolerance enabled by AWS infrastructure.","Increased capital expenditure for redundant on-premises hardware."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) directly addresses the concern for application accessibility during a data center outage. AWS''s infrastructure is designed for high availability and fault tolerance, allowing customers to deploy applications across multiple Availability Zones within a Region, ensuring that an outage in one AZ does not affect the application. Option A (incorrect) represents an anti-pattern ([ap-1.2-004]) as deploying to a single Availability Zone creates a single point of failure and does not ensure high availability. Option B (incorrect) misrepresents the shared responsibility model; customers are still responsible for security ''in'' the cloud. Option D (incorrect) refers to on-premises hardware and capital expenditure, which is the opposite of leveraging AWS cloud benefits for high availability.', 60, 'm_60_1', 4, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company is designing a new web application that needs to handle varying user loads throughout the day, automatically scaling capacity up or down to match demand. They also want to ensure that individual server failures do not impact the overall application availability. Which AWS design principles should be prioritized?', '["Deploying to a single Availability Zone and manually scaling EC2 instances.","Implementing elasticity and designing for failure.","Building tightly coupled application components for simplified management.","Treating EC2 instances as pets that require unique, manual configuration."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) aligns with AWS design principles. Implementing elasticity (e.g., with AWS Auto Scaling) allows the application to automatically adjust capacity to demand. Designing for failure (e.g., deploying across multiple Availability Zones and using load balancers) ensures that individual server failures do not impact overall availability. Option A (incorrect) represents an anti-pattern ([ap-1.2-004]) by deploying to a single Availability Zone, which creates a single point of failure, and manual scaling contradicts the need for automatic adaptation. Option C (incorrect) represents an anti-pattern ([ap-1.2-002]) as tightly coupled components can lead to cascading failures and hinder independent scaling. Option D (incorrect) represents an anti-pattern ([ap-1.2-001]) as treating instances as pets prevents automation, auto-scaling, and rapid recovery.', 60, 'm_60_4', 5, NULL, NULL),
  ('mock_60_all_1775002619521', 'A development team is building a microservices-based application where different components communicate asynchronously. They want to ensure that a failure in one service does not cascade and bring down the entire application. Which AWS design principle is most crucial for achieving this goal?', '["Deploying all microservices on a single, large Amazon EC2 instance.","Implementing synchronous API calls between all services for immediate feedback.","Decoupling components using message queues or event streams.","Manually managing server configurations to ensure consistency."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) aligns with the design principle of decoupling components. Using message queues (like Amazon SQS) or event streams (like Amazon Kinesis) allows services to communicate asynchronously, so a failure in one service does not directly impact others, preventing cascading failures and enabling independent scaling. Option A (incorrect) would create a monolithic application on a single point of failure, directly opposing the benefits of microservices and decoupling. Option B (incorrect) promotes tight coupling ([ap-1.2-002]), where synchronous calls mean a failure in one service would immediately block the calling service. Option D (incorrect) relates to operational excellence but does not directly address fault isolation between application components, and manual management is generally an anti-pattern ([ap-1.2-001]) in the cloud.', 60, 'm_60_4', 6, NULL, NULL),
  ('mock_60_all_1775002619521', 'An organization wants to implement a disaster recovery strategy for its critical applications. They aim to achieve rapid recovery by being able to quickly provision an entirely new environment from scratch if the primary region becomes unavailable. Which AWS design principle supports this approach?', '["Manually configuring each server in the recovery environment to ensure uniqueness.","Treating infrastructure as long-lived, immutable resources that are rarely changed.","Building tightly coupled architectures to simplify cross-region data synchronization.","Leveraging disposable resources and infrastructure as code for automation."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) aligns with the principle of disposable resources and infrastructure as code. This approach allows environments to be defined in code (e.g., AWS CloudFormation) and provisioned rapidly and consistently, making disaster recovery faster and more reliable. Option A (incorrect) represents an anti-pattern ([ap-1.2-001]) as manual configuration is slow, error-prone, and contradicts the goal of rapid, consistent provisioning. Option B (incorrect) contradicts the idea of disposable resources; while immutability is a good practice, ''long-lived'' and ''rarely changed'' doesn''t fit the rapid provisioning for DR. Option C (incorrect) represents an anti-pattern ([ap-1.2-002]) as tightly coupled architectures complicate disaster recovery and make independent component recovery difficult.', 60, 'm_60_4', 7, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is reviewing its existing AWS architecture to identify potential weaknesses in security, reliability, and cost-efficiency. They need a structured approach to evaluate their design against AWS best practices across multiple dimensions. Which AWS tool or framework should they utilize?', '["The AWS Well-Architected Framework.","AWS Pricing Calculator for cost estimation only.","AWS Migration Hub for tracking migration progress.","AWS Database Migration Service (DMS) for database-specific issues."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the AWS Well-Architected Framework, which provides a structured approach to evaluate architectures against best practices across six pillars: operational excellence, security, reliability, performance efficiency, cost optimization, and sustainability. This directly addresses the need to identify weaknesses across multiple dimensions. Option B (incorrect) is useful for cost estimation but does not provide a comprehensive architectural review across all pillars. Option C (incorrect) is for tracking migration progress and does not evaluate existing architecture against best practices. Option D (incorrect) is a service for migrating databases and is not a framework for overall architectural review.', 60, 'm_60_4', 8, NULL, NULL),
  ('mock_60_all_1775002619521', 'A team manages several Amazon EC2 instances that host a stateless web application. They need to ensure that if an instance becomes unhealthy, it is automatically replaced without manual intervention, and the application continues to operate without interruption. Which design principle and service combination best achieves this?', '["Manually monitoring instance health and replacing failed instances as needed.","Designing for failure by using AWS Auto Scaling groups across multiple Availability Zones.","Deploying all instances in a single Availability Zone to simplify network configuration.","Treating each EC2 instance as a unique, critical server requiring individual care."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) embodies the design principle of designing for failure and utilizes AWS Auto Scaling groups across multiple Availability Zones. This ensures that unhealthy instances are automatically replaced, and the application maintains high availability even if an entire AZ experiences issues. Option A (incorrect) involves manual intervention, which contradicts the requirement for automatic replacement and increases operational overhead. Option C (incorrect) represents an anti-pattern ([ap-1.2-004]) as deploying to a single Availability Zone creates a single point of failure. Option D (incorrect) represents an anti-pattern ([ap-1.2-001]) as treating instances as pets prevents automation and rapid replacement, hindering fault tolerance.', 60, 'm_60_4', 9, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A media company currently uses on-premises servers for video rendering, incurring significant upfront costs for hardware and licenses. They want to shift to a model where they only pay for the compute resources when rendering jobs are active, reducing fixed costs. Which cloud economics concept is most relevant to this transition?', '["Increasing capital expenditure (CapEx) for future hardware purchases.","Ignoring resource utilization to ensure maximum capacity is always available.","Shifting from capital expenditure (CapEx) to operational expenditure (OpEx).","Purchasing Reserved Instances for intermittent, short-duration workloads."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes the fundamental shift from CapEx to OpEx, which is a core benefit of cloud economics. By moving to AWS, the company avoids large upfront hardware investments (CapEx) and instead pays for compute resources as they are consumed (OpEx), aligning costs with actual usage. Option A (incorrect) contradicts the goal of reducing upfront costs. Option B (incorrect) leads to over-provisioning and wasted costs, which is an anti-pattern ([ap-1.1-004]) in cloud economics. Option D (incorrect) is generally not cost-effective for intermittent, short-duration workloads; Reserved Instances are better suited for steady-state, predictable usage.', 60, 'm_60_3', 10, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company has several development and test environments running on Amazon EC2 instances that are only used during business hours (9 AM to 5 PM, Monday to Friday). They want to optimize costs for these non-production workloads. Which strategy is MOST cost-effective?', '["Running all EC2 instances 24/7 to ensure continuous availability.","Shutting down EC2 instances outside of business hours.","Purchasing Reserved Instances for all development and test environments.","Over-provisioning EC2 instances to handle potential future spikes in demand."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the most cost-effective strategy. By shutting down EC2 instances when they are not in use, the company avoids paying for compute time during off-hours, directly leveraging the pay-as-you-go model. Option A (incorrect) represents an anti-pattern ([ap-1.1-004]) as it leads to unnecessary costs by running resources 24/7 when they are only needed part-time. Option C (incorrect) is not ideal for intermittent usage; Reserved Instances are best for steady-state workloads, and purchasing them for instances that are frequently shut down would not be cost-effective. Option D (incorrect) leads to wasted resources and higher costs, contradicting cost optimization principles.', 60, 'm_60_3', 11, NULL, NULL),
  ('mock_60_all_1775002619521', 'A startup is launching a new application and needs a database solution. They want to minimize the administrative burden of database management, including patching, backups, and scaling, to focus their limited engineering resources on application development. Which AWS service type best meets this requirement for LEAST operational overhead?', '["Running a self-managed database on an Amazon EC2 instance.","Using a database that requires manual patching and backup scripts.","Leveraging a fully managed database service like Amazon RDS or Amazon DynamoDB.","Implementing a custom database solution that needs constant monitoring by the development team."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the best choice for minimizing operational overhead. Fully managed database services like Amazon RDS (for relational databases) or Amazon DynamoDB (for NoSQL databases) handle tasks such as patching, backups, scaling, and high availability automatically, freeing up engineering resources. Option A (incorrect) would require the startup to manage all database administration tasks themselves, increasing operational burden. Option B (incorrect) explicitly states manual patching and backups, which contradicts the goal of minimizing administrative burden. Option D (incorrect) would require significant ongoing effort from the development team, increasing operational overhead.', 60, 'm_60_3', 12, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is migrating its existing applications to AWS. They have identified that many of their current Amazon EC2 instances are over-provisioned, meaning they have more CPU and memory than their workloads actually require. Which cost optimization principle should they apply to address this issue?', '["Purchasing more powerful EC2 instances to accommodate potential future growth.","Right-sizing EC2 instances to match workload requirements.","Ignoring resource utilization metrics to simplify management.","Running all instances 24/7 to ensure maximum uptime, regardless of usage."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the principle of right-sizing, which involves analyzing resource utilization and adjusting instance types to match the actual needs of the workload. This ensures that the company pays only for the resources it truly uses, optimizing costs. Option A (incorrect) would exacerbate the over-provisioning problem and increase costs. Option C (incorrect) is an anti-pattern as ignoring utilization metrics prevents effective cost optimization. Option D (incorrect) is an anti-pattern ([ap-1.1-004]) that leads to unnecessary costs, especially for non-production or intermittent workloads.', 60, 'm_60_3', 13, NULL, NULL),
  ('mock_60_all_1775002619521', 'A business is evaluating the total cost of ownership (TCO) for migrating its on-premises data center to AWS. They need a tool to estimate the costs of various AWS services and compare them with their current on-premises expenses, including servers, storage, networking, and personnel. Which AWS tool is designed for this purpose?', '["AWS Well-Architected Tool for architectural best practices.","AWS Migration Hub for tracking migration status.","AWS Pricing Calculator for estimating cloud costs.","AWS Database Migration Service (DMS) for database migration costs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Pricing Calculator, which allows users to estimate the costs of various AWS services and compare them with their current on-premises expenses, providing a comprehensive TCO analysis. Option A (incorrect) is for evaluating architectural best practices, not for cost estimation. Option B (incorrect) is used to track the progress of migrations, not to calculate TCO. Option D (incorrect) is a service for migrating databases and would only cover a small part of the overall TCO calculation.', 60, 'm_60_3', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_60_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A large enterprise plans to migrate hundreds of on-premises applications to AWS. They want to quickly move these applications to the cloud with minimal changes to the application code or architecture, prioritizing speed over immediate cloud-native optimization. Which migration strategy is most appropriate for this goal?', '["Refactor, which involves re-architecting applications for cloud-native services.","Replatform, which involves making some cloud optimizations without changing core architecture.","Repurchase, which means replacing existing applications with SaaS solutions.","Rehost, also known as ''lift and shift'', moving applications as-is to EC2."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) describes the ''Rehost'' (lift and shift) strategy, which involves moving applications to AWS EC2 instances with minimal or no changes. This is the fastest approach for migrating a large number of applications, prioritizing speed over immediate cloud-native optimization. Option A (incorrect) ''Refactor'' involves significant re-architecture, which is time-consuming and contradicts the goal of quick migration with minimal changes ([ap-1.3-001]). Option B (incorrect) ''Replatform'' involves some changes to leverage cloud features, making it slower than rehosting. Option C (incorrect) ''Repurchase'' involves replacing applications with new SaaS solutions, which is a different strategy altogether and may not be feasible for all existing applications.', 60, 'm_60_2', 15, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company has a legacy database running on-premises that needs to be migrated to a fully managed database service on AWS, such as Amazon RDS, to reduce operational overhead. They need a service that can facilitate this migration with minimal downtime and ensure data consistency. Which AWS service is best suited for this task?', '["AWS Database Migration Service (DMS).","AWS Snow Family for large-scale data transfer.","AWS Application Migration Service for server migration.","AWS Pricing Calculator for migration cost estimation."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the AWS Database Migration Service (DMS), which is specifically designed to migrate databases to AWS quickly and securely, with minimal downtime. It supports various database engines and can perform both one-time migrations and continuous data replication. Option B (incorrect) is used for transferring very large amounts of data physically, not for migrating live databases with minimal downtime. Option C (incorrect) is used for migrating entire servers (EC2 instances), not specifically for migrating and transforming databases to managed services. Option D (incorrect) is for estimating costs, not for performing the migration itself.', 60, 'm_60_2', 16, NULL, NULL),
  ('mock_60_all_1775002619521', 'An organization is preparing for a large-scale cloud migration and wants to ensure that all aspects of their business, people, and technology are ready for the transition. They need a structured framework to guide their preparation and address potential challenges. Which AWS framework should they utilize?', '["The AWS Well-Architected Framework for technical best practices.","The AWS Cloud Adoption Framework (AWS CAF) for comprehensive guidance.","AWS Migration Hub for tracking individual application migration status.","AWS Pricing Calculator for financial planning and cost comparison."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the AWS Cloud Adoption Framework (AWS CAF), which provides comprehensive guidance across six perspectives (Business, People, Governance, Platform, Security, Operations) to help organizations prepare for and execute a successful cloud migration. This addresses the need to consider all aspects beyond just technology. Option A (incorrect) focuses on technical architectural best practices, not the broader organizational readiness for migration. Option C (incorrect) is a service for tracking the progress of migrations, not a framework for planning and assessing readiness. Option D (incorrect) is for estimating costs and TCO, not for guiding the overall adoption process.', 60, 'm_60_2', 17, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to migrate petabytes of on-premises data to Amazon S3. Their internet connectivity is limited, making a direct online transfer impractical and time-consuming. Which AWS service family is designed for securely and efficiently transferring large volumes of data with limited network bandwidth?', '["AWS Database Migration Service (DMS) for database transfers.","AWS Application Migration Service for server rehosting.","AWS Snow Family for physical data transfer devices.","AWS Direct Connect for establishing dedicated network connections."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the AWS Snow Family, which includes devices like AWS Snowball and AWS Snowmobile, specifically designed for physically transferring petabytes of data into or out of AWS when network bandwidth is a limiting factor. Option A (incorrect) is for migrating databases, not general petabyte-scale file data. Option B (incorrect) is for migrating entire servers (EC2 instances), not for bulk data transfer to Amazon S3. Option D (incorrect) AWS Direct Connect provides dedicated network connections but still relies on network bandwidth, which is stated as limited and impractical for petabytes of data in this scenario.', 60, 'm_60_2', 18, NULL, NULL),
  ('mock_60_all_1775002619521', 'A software vendor wants to move its monolithic application to AWS. They decide to first rehost the application on Amazon EC2 instances to gain immediate cloud benefits, and then gradually break it down into microservices and use AWS Lambda and Amazon ECS over time. Which cloud adoption strategy does this approach represent?', '["Refactor, by immediately re-architecting the entire application.","Repurchase, by replacing the application with a SaaS solution.","Retain, by keeping the application on-premises indefinitely.","A phased approach combining Rehost and Refactor."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) accurately describes a phased migration approach that combines ''Rehost'' (lift and shift to EC2) for initial speed and immediate cloud benefits, followed by ''Refactor'' (re-architecting into microservices with AWS Lambda and Amazon ECS) for long-term optimization. This is a common and effective strategy. Option A (incorrect) ''Refactor'' implies doing all re-architecture at once, which is an anti-pattern ([ap-1.3-001]) as it''s risky and slow. Option B (incorrect) ''Repurchase'' means replacing the application, which is not what the scenario describes. Option C (incorrect) ''Retain'' means keeping it on-premises, which contradicts the goal of moving to AWS.', 60, 'm_60_2', 19, NULL, NULL);

