INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A small development team needs to access an AWS account for daily operations. They require individual access, and the company wants to enforce strong authentication practices while minimizing the risk of credential compromise. Which approach provides the LEAST risk of credential compromise?', '["Create individual IAM users for each team member, enable Multi-Factor Authentication (MFA) for each user, and instruct them to use these credentials for all tasks.","Share the AWS account root user credentials among the team members, ensuring they all know the password and can access resources.","Create a single IAM user with AdministratorAccess policy, share its credentials among the team, and rotate the password monthly.","Generate AWS access keys for each team member and embed them directly into their local development environment for quick access."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) adheres to the principle of least privilege by creating individual IAM users and significantly reduces the risk of credential compromise by enabling Multi-Factor Authentication (MFA). This ensures accountability and adds an extra layer of security. Option B (incorrect) is an anti-pattern ([ap-2.3-001], [ap-2.3-003]) as sharing root user credentials is highly insecure and violates the principle of individual accountability. Option C (incorrect) is also an anti-pattern ([ap-2.3-003]) because sharing IAM user credentials eliminates accountability and granting AdministratorAccess broadly violates the principle of least privilege ([ap-2.3-002]). Option D (incorrect) is an anti-pattern ([ap-2.3-005]) as embedding long-term access keys directly into development environments or code is a major security risk and makes credential rotation difficult.', 61, 'm_61_3', 1, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company has multiple applications running on Amazon EC2 instances that need to interact with Amazon S3 buckets to store and retrieve data. The security team mandates that no long-term AWS credentials should be stored directly on the EC2 instances. Which IAM capability should be used to grant these EC2 instances secure access to Amazon S3?', '["Create an IAM role with the necessary Amazon S3 permissions and attach it to the Amazon EC2 instances.","Generate IAM user access keys for each Amazon EC2 instance and store them securely in a configuration file on the instance.","Embed the AWS account root user access keys directly into the application code running on the Amazon EC2 instances.","Configure an Amazon S3 bucket policy to allow public access from the IP addresses of the Amazon EC2 instances."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the AWS recommended best practice for granting permissions to applications running on Amazon EC2 instances. IAM roles provide temporary credentials that are automatically rotated, eliminating the need to store long-term AWS credentials on the instances, thereby reducing the risk of compromise ([ap-2.3-005]). Option B (incorrect) involves storing long-term credentials on the instance, which is explicitly what the security team wants to avoid. Option C (incorrect) is a severe security anti-pattern ([ap-2.3-001], [ap-2.3-005]) as it exposes the highly privileged root user credentials, making the entire account vulnerable. Option D (incorrect) would grant public access to the S3 bucket, which is a major security risk for sensitive data and does not provide instance-level access control.', 61, 'm_61_3', 2, NULL, NULL),
  ('mock_60_all_1775002619521', 'A new AWS account has been created for a startup. The first task is to set up secure administrative access for the lead developer, ensuring that the highest level of privilege is protected and not used for routine operations. Which action should be taken FIRST to establish secure administrative access according to AWS best practices?', '["Create an IAM user for the lead developer, grant it AdministratorAccess, and enable Multi-Factor Authentication (MFA) for this IAM user.","Immediately use the root user credentials to perform all initial setup and configuration tasks, then secure them.","Create an IAM group with AdministratorAccess, add the lead developer''s IAM user to it, and share the root user credentials for emergencies.","Configure the root user with a very strong password and use it for all administrative tasks, as it has full control."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) follows AWS best practices by creating a dedicated IAM user for administrative tasks, granting necessary permissions, and crucially, enabling Multi-Factor Authentication (MFA) for enhanced security ([ap-2.3-004]). The root user should be secured and used only for tasks that specifically require root privileges. Option B (incorrect) is an anti-pattern ([ap-2.3-001]) as the root user should be used as little as possible due to its unrestricted access. Option C (incorrect) is an anti-pattern ([ap-2.3-003]) because sharing root user credentials is a major security risk and violates accountability. Option D (incorrect) is an anti-pattern ([ap-2.3-001]) as using the root user for all administrative tasks exposes the account to significant risk if those credentials are compromised.', 61, 'm_61_3', 3, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to manage access for its employees to multiple AWS accounts within an AWS Organization. They want a centralized solution that allows employees to sign in once and access all authorized accounts and applications without managing individual IAM users in each account. Which AWS service is designed to provide this centralized access management with single sign-on capabilities?', '["AWS IAM Identity Center (SSO)","AWS Identity and Access Management (IAM)","Amazon Cognito","AWS Directory Service"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS IAM Identity Center (SSO), which provides centralized access management to multiple AWS accounts and business applications, allowing users to sign in once and access everything they need. Option B (incorrect) is AWS Identity and Access Management (IAM), which manages users, groups, roles, and policies within a single AWS account, but does not inherently provide centralized single sign-on across multiple accounts without additional configuration. Option C (incorrect) is Amazon Cognito, primarily used for managing user identities for web and mobile applications, not for centralized access to AWS accounts. Option D (incorrect) is AWS Directory Service, which allows you to set up and run Microsoft Active Directory or connect to your existing on-premises directory, but it''s a component often used *with* IAM Identity Center for identity sources, not the SSO service itself.', 61, 'm_61_3', 4, NULL, NULL),
  ('mock_60_all_1775002619521', 'A developer needs to grant an application running on an Amazon EC2 instance temporary, specific permissions to interact with an Amazon DynamoDB table. The principle of least privilege must be followed, and credentials should be automatically rotated. Which IAM best practice should the developer implement to meet these requirements?', '["Create an IAM user with full Amazon DynamoDB access, generate access keys, and configure the application to use them.","Modify the Amazon DynamoDB table policy to allow public access for the specific actions required by the application.","Grant the Amazon EC2 instance''s security group outbound access to Amazon DynamoDB endpoints.","Attach an IAM role with only the necessary Amazon DynamoDB permissions to the Amazon EC2 instance."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS recommended best practice. Attaching an IAM role with specific, least-privilege permissions to an Amazon EC2 instance allows the application to obtain temporary, automatically rotated credentials, eliminating the need to store long-term credentials and adhering to the principle of least privilege. Option A (incorrect) violates the principle of least privilege by granting full access ([ap-2.3-002]) and requires managing long-term access keys, which is a security risk ([ap-2.3-005]). Option B (incorrect) would grant public access to the DynamoDB table, which is a significant security vulnerability for sensitive data. Option C (incorrect) only controls network traffic at the instance level and does not grant or manage AWS service permissions; it''s a network security control, not an access management control.', 61, 'm_61_3', 5, NULL, NULL),
  ('mock_60_all_1775002619521', 'A small development team operates an application on an Amazon EC2 instance that needs to regularly upload application logs to an Amazon S3 bucket. The team wants to implement a solution that grants the EC2 instance temporary, secure access to the S3 bucket without embedding long-term credentials, adhering to the principle of least privilege. Which approach is MOST secure and compliant with AWS best practices?', '["Attach an IAM role to the EC2 instance with specific permissions to write to the S3 bucket.","Create an IAM user with S3 write permissions, generate access keys, and store them securely on the EC2 instance.","Use the AWS account root user credentials directly on the EC2 instance to upload logs to the S3 bucket.","Configure the S3 bucket policy to allow public write access from any IP address for the EC2 instance."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is the most secure and recommended approach. Attaching an IAM role to an Amazon EC2 instance allows the instance to obtain temporary credentials that are automatically rotated, eliminating the need to manage long-term access keys. This adheres to the principle of least privilege and best practices for securing applications on EC2. Option B (incorrect) involves creating an IAM user and storing long-term access keys on the EC2 instance. This is an anti-pattern (ap-2.3-005) because these credentials could be compromised if the instance is breached, and managing their rotation is an operational burden. Option C (incorrect) is a severe anti-pattern (ap-2.3-001) as the root user has unrestricted access to the entire AWS account and should never be used for daily operational tasks or on EC2 instances. Option D (incorrect) is a major security vulnerability. Allowing public write access to an S3 bucket (even if restricted by IP, which is difficult to manage for dynamic EC2 IPs) is an anti-pattern (ap-2.3-002) that grants overly broad permissions and exposes the bucket to unauthorized access from the internet.', 61, 'm_61_3', 6, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_61_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company wants to protect its web application, hosted on Amazon EC2 instances behind an Application Load Balancer, from common web exploits and bots. They need a service that can filter malicious traffic before it reaches their application. Which AWS service should be implemented to provide this layer of protection?', '["AWS WAF","Amazon GuardDuty","AWS Shield Standard","Network Access Control Lists (NACLs)"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS WAF (Web Application Firewall), which helps protect web applications from common web exploits that could affect application availability, compromise security, or consume excessive resources. It allows you to control which traffic reaches your applications by creating security rules. Option B (incorrect) is Amazon GuardDuty, a threat detection service that continuously monitors for malicious activity and unauthorized behavior, but it does not filter incoming web traffic. Option C (incorrect) is AWS Shield Standard, which provides automatic DDoS protection at the network and transport layers, but does not protect against application-layer web exploits. Option D (incorrect) are Network Access Control Lists (NACLs), which operate at the subnet level and are stateless, providing a coarse-grained firewall, but are not designed for granular web exploit protection like WAF ([ap-2.4-001]).', 61, 'm_61_4', 7, NULL, NULL),
  ('mock_60_all_1775002619521', 'A security team needs to continuously monitor their AWS accounts for malicious activity and unauthorized behavior, such as unusual API calls or potential compromised instances. They require an automated threat detection service that uses machine learning and threat intelligence. Which AWS service should they enable to meet this requirement with minimal effort?', '["AWS Security Hub","Amazon GuardDuty","AWS CloudTrail","Amazon Inspector"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is Amazon GuardDuty, a threat detection service that continuously monitors your AWS accounts and workloads for malicious activity and unauthorized behavior to protect your AWS accounts, workloads, and data stored in Amazon S3. It uses machine learning, anomaly detection, and integrated threat intelligence. Option A (incorrect) is AWS Security Hub, which aggregates, organizes, and prioritizes security findings from various AWS services and partner products, but does not perform the primary threat detection itself. Option C (incorrect) is AWS CloudTrail, which records API calls and related events, providing an audit trail, but it does not actively detect threats or malicious activity using machine learning. Option D (incorrect) is Amazon Inspector, a vulnerability management service that scans Amazon EC2 instances and container images for software vulnerabilities and unintended network exposure, not for general malicious activity detection.', 61, 'm_61_4', 8, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company stores vast amounts of data in Amazon S3 buckets, including customer information and financial records. They need to identify and protect sensitive data like Personally Identifiable Information (PII) to ensure compliance with data privacy regulations. Which AWS service can automatically discover, classify, and report on sensitive data in Amazon S3?', '["AWS Config","Amazon GuardDuty","AWS CloudTrail","Amazon Macie"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is Amazon Macie, a data security and data privacy service that uses machine learning and pattern matching to discover and protect sensitive data in AWS, primarily in Amazon S3. It automatically identifies PII and other sensitive data, providing visibility into potential risks. Option A (incorrect) is AWS Config, which monitors and records AWS resource configurations and changes, assessing compliance against desired configurations, but it does not specifically discover sensitive data within content. Option B (incorrect) is Amazon GuardDuty, a threat detection service that monitors for malicious activity and unauthorized behavior, not for sensitive data discovery within S3 objects. Option C (incorrect) is AWS CloudTrail, which logs API calls and user activity, providing an audit trail, but does not analyze the content of data stored in S3 for sensitivity ([ap-2.4-003]).', 61, 'm_61_4', 9, NULL, NULL),
  ('mock_60_all_1775002619521', 'A new AWS customer is concerned about potential Distributed Denial of Service (DDoS) attacks against their public-facing applications. They want to understand what baseline protection AWS offers automatically without any additional cost or configuration. Which AWS service provides automatic, always-on DDoS protection for all AWS customers at no additional charge?', '["AWS WAF","AWS Shield Advanced","Amazon GuardDuty","AWS Shield Standard"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Shield Standard, which is automatically enabled for all AWS customers at no additional cost. It provides always-on detection and automatic inline mitigations against common, most frequently occurring network and transport layer (Layer 3 and 4) DDoS attacks. Option A (incorrect) is AWS WAF, a web application firewall that protects against web exploits, but it is not free and requires configuration. Option B (incorrect) is AWS Shield Advanced, which provides enhanced DDoS protection and is a paid service. Option C (incorrect) is Amazon GuardDuty, a threat detection service that monitors for malicious activity, but it does not provide DDoS protection ([ap-2.4-004]).', 61, 'm_61_4', 10, NULL, NULL),
  ('mock_60_all_1775002619521', 'A security operations team manages multiple AWS accounts and uses several AWS security services like Amazon GuardDuty, Amazon Inspector, and Amazon Macie. They need a single place to aggregate, organize, and prioritize security findings from all these services for efficient incident response. Which AWS service provides a comprehensive view of security alerts and automated compliance checks?', '["AWS CloudTrail","AWS Config","Amazon Detective","AWS Security Hub"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Security Hub, which provides a comprehensive view of your security state in AWS and helps you check your compliance with security industry standards and best practices. It collects security data from across AWS accounts, services (like GuardDuty, Inspector, Macie), and partner solutions, then helps you analyze your security trends and identify the highest priority security issues. Option A (incorrect) is AWS CloudTrail, which logs API calls and user activity, providing an audit trail, but does not aggregate or prioritize security findings. Option B (incorrect) is AWS Config, which monitors resource configurations and assesses compliance, but it doesn''t centralize findings from other security services. Option C (incorrect) is Amazon Detective, which helps investigate security findings by using machine learning, graph theory, and statistical analysis to build a unified, interactive view of resource behaviors and interactions over time, but it''s for investigation, not primary aggregation and prioritization of findings ([ap-2.4-005]).', 61, 'm_61_4', 11, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company hosts its public-facing web application on AWS and is concerned about potential Distributed Denial of Service (DDoS) attacks. They require a solution that provides automatic baseline protection against common network and transport layer attacks without incurring any additional costs. Which AWS service provides this capability?', '["AWS WAF, configured with custom rules to block malicious traffic patterns.","AWS Shield Standard, which is automatically enabled for all AWS customers.","Amazon GuardDuty, to detect unusual activity and potential threats to the application.","AWS Firewall Manager, to centrally manage firewall rules across multiple accounts and VPCs."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Shield Standard, which is automatically enabled for all AWS customers at no additional cost. It provides always-on detection and automatic inline mitigations that protect against common, most frequently occurring network and transport layer DDoS attacks. This directly addresses the requirement for baseline protection without additional cost. Option A (incorrect) refers to AWS WAF, which provides application layer protection and requires configuration of custom rules, incurring additional costs based on rules and requests. While valuable, it doesn''t meet the ''no additional cost'' and ''baseline'' criteria as effectively as Shield Standard. Option C (incorrect) describes Amazon GuardDuty, which is a threat detection service that monitors for malicious activity and unauthorized behavior, but it does not directly provide DDoS protection. Option D (incorrect) is AWS Firewall Manager, a service for centrally configuring and managing firewall rules across multiple accounts, which is an advanced governance tool and not a direct DDoS protection service for a single application at no cost.', 61, 'm_61_4', 12, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_61_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company needs to demonstrate compliance with industry standards and regulations to its auditors. They require access to AWS''s own compliance reports, certifications, and agreements, such as SOC reports or PCI DSS attestations. Which AWS service provides on-demand access to these AWS compliance resources?', '["AWS Audit Manager","AWS Trusted Advisor","AWS Artifact","AWS Config"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Artifact, a service that provides on-demand access to AWS''s security and compliance reports and select online agreements. This includes SOC reports, PCI DSS attestations, and other certifications that demonstrate AWS''s compliance posture. Option A (incorrect) is AWS Audit Manager, which helps automate the collection of evidence to make it easier to audit your AWS usage against controls, but it does not provide AWS''s own compliance reports. Option B (incorrect) is AWS Trusted Advisor, which provides recommendations for optimizing performance, security, cost, and fault tolerance, but it does not offer compliance reports. Option D (incorrect) is AWS Config, which monitors and records AWS resource configurations and changes, assessing compliance against desired configurations, but it does not provide AWS''s internal compliance documentation.', 61, 'm_61_2', 13, NULL, NULL),
  ('mock_60_all_1775002619521', 'A financial institution is storing sensitive customer data in Amazon S3 and Amazon RDS databases. They are required to encrypt all data at rest to meet regulatory compliance standards. They also need to manage the encryption keys centrally and securely. Which AWS service should they use to manage their encryption keys for these services?', '["AWS Secrets Manager","AWS Certificate Manager (ACM)","AWS Systems Manager Parameter Store","AWS Key Management Service (KMS)"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Key Management Service (KMS), which makes it easy for you to create and manage cryptographic keys and control their use across a wide range of AWS services and in your applications. It provides a centralized and secure way to manage encryption keys for data at rest in services like Amazon S3 and Amazon RDS. Option A (incorrect) is AWS Secrets Manager, which helps you manage, retrieve, and rotate database credentials, API keys, and other secrets throughout their lifecycle, but it is not primarily for managing encryption keys for data at rest. Option B (incorrect) is AWS Certificate Manager (ACM), which manages SSL/TLS certificates for your AWS services, not encryption keys for data. Option C (incorrect) is AWS Systems Manager Parameter Store, which provides secure, hierarchical storage for configuration data management and secrets management, but AWS KMS is specifically designed for cryptographic key management with deeper integration for encryption across AWS services ([ap-2.2-003]).', 61, 'm_61_2', 14, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company operates in a highly regulated industry and needs to maintain a detailed audit trail of all API calls made to their AWS resources. This audit trail is crucial for security analysis, compliance auditing, and operational troubleshooting. Which AWS service should be enabled to record and store a history of all API calls and related events in the AWS account?', '["AWS Config","Amazon CloudWatch","AWS CloudTrail","AWS Security Hub"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS CloudTrail, which enables governance, compliance, operational auditing, and risk auditing of your AWS account. With CloudTrail, you can log, continuously monitor, and retain account activity related to actions across your AWS infrastructure, including API calls made through the AWS Management Console, AWS SDKs, command line tools, and other AWS services. Option A (incorrect) is AWS Config, which records configuration changes of your AWS resources, but it does not provide a detailed audit trail of API calls. Option B (incorrect) is Amazon CloudWatch, a monitoring and observability service that collects and processes raw data into readable, near real-time metrics and logs, but it''s not specifically designed for API call auditing. Option D (incorrect) is AWS Security Hub, which aggregates security findings from various services, but it does not generate the API call audit trail itself ([ap-2.2-002]).', 61, 'm_61_2', 15, NULL, NULL),
  ('mock_60_all_1775002619521', 'An organization with multiple AWS accounts wants to enforce guardrails across all accounts to prevent users from deploying resources that violate company policies, regardless of the IAM permissions granted within individual accounts. For example, they want to restrict launching Amazon EC2 instances in specific regions. Which AWS service and feature combination should be used to implement these preventative controls?', '["AWS Identity and Access Management (IAM) policies applied to individual users.","AWS Organizations with Service Control Policies (SCPs).","AWS Config rules deployed in each account.","Amazon GuardDuty to detect non-compliant resource launches."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Organizations with Service Control Policies (SCPs). SCPs are a type of organization policy that you can use to manage permissions in your organization. They offer central control over the maximum available permissions for all accounts in your organization, acting as guardrails that even an account''s root user cannot override. Option A (incorrect) is AWS Identity and Access Management (IAM) policies, which are applied within individual accounts and can be overridden or misconfigured by administrators in those accounts, failing to provide organization-wide preventative guardrails. Option C (incorrect) is AWS Config rules, which are detective controls that assess compliance after resources are deployed, not preventative controls that block actions. Option D (incorrect) is Amazon GuardDuty, a threat detection service, which is a detective control and does not prevent actions from being taken ([ap-2.2-004]).', 61, 'm_61_2', 16, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to ensure that their AWS resources comply with internal configuration standards and external regulatory requirements. They want to continuously monitor resource configurations for changes and automatically assess compliance against predefined rules. Which AWS service is best suited for recording configuration changes and evaluating resources against desired configurations?', '["AWS CloudTrail","Amazon CloudWatch","AWS Config","AWS Security Hub"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Config, which continuously monitors and records your AWS resource configurations and allows you to automate the evaluation of recorded configurations against desired configurations. It''s ideal for assessing compliance, auditing changes, and ensuring adherence to internal and external standards. Option A (incorrect) is AWS CloudTrail, which logs API calls and user activity, providing an audit trail of actions taken in the account, but it does not focus on resource configuration states or compliance assessment. Option B (incorrect) is Amazon CloudWatch, a monitoring service for AWS resources and applications, which collects metrics and logs, but it does not specifically track configuration changes or assess compliance against rules. Option D (incorrect) is AWS Security Hub, which aggregates security findings and performs automated security checks, but AWS Config is the primary service for continuous configuration monitoring and compliance assessment ([ap-2.2-002]).', 61, 'm_61_2', 17, NULL, NULL),
  ('mock_60_all_1775002619521', 'A financial institution needs to maintain a comprehensive audit trail of all actions performed within its AWS accounts for compliance and security investigations. They require a service that records all API calls made by users, roles, and AWS services, ensuring the logs are immutable and easily accessible for review. Which AWS service should they enable to meet this requirement?', '["Amazon GuardDuty, to continuously monitor for malicious activity and unauthorized behavior.","AWS Config, to record configuration changes to AWS resources over time.","AWS CloudTrail, to log all API calls and related events in the AWS account.","Amazon Macie, to discover and protect sensitive data stored in Amazon S3 buckets."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS CloudTrail. It provides a record of actions taken by a user, role, or an AWS service in AWS. CloudTrail logs all API calls, including console actions, CLI commands, and SDK requests, and delivers them to an Amazon S3 bucket, creating an immutable audit trail essential for compliance and security investigations. Option A (incorrect) describes Amazon GuardDuty, which is a threat detection service that monitors for malicious activity and unauthorized behavior, but it does not provide a comprehensive log of all API calls for auditing purposes. Option B (incorrect) describes AWS Config, which records configuration changes of AWS resources, allowing for compliance auditing of resource configurations, but it does not log API calls. Option D (incorrect) describes Amazon Macie, which is a data security and privacy service that uses machine learning to discover, classify, and protect sensitive data in Amazon S3, but it is not an API logging service.', 61, 'm_61_2', 18, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_61_1
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company is deploying a web application on Amazon EC2 instances. They are responsible for ensuring the operating system running on these instances is regularly patched and secured against vulnerabilities. According to the AWS shared responsibility model, which party is primarily responsible for patching the guest operating system on these Amazon EC2 instances?', '["AWS, as part of security OF the cloud.","The customer, as part of security IN the cloud.","A third-party security vendor contracted by AWS.","AWS and the customer share this responsibility equally, with AWS performing the patching."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) correctly identifies the customer''s responsibility. For Infrastructure as a Service (IaaS) like Amazon EC2, the customer is responsible for ''security IN the cloud,'' which includes managing the guest operating system (including updates and security patches), application software, and security configuration of their instances. Option A (incorrect) describes AWS''s responsibility for ''security OF the cloud,'' which covers the underlying infrastructure, hardware, and hypervisor, but not the guest OS. Option C (incorrect) is not part of the standard shared responsibility model. Option D (incorrect) misrepresents the division of responsibility; for EC2 guest OS patching, it is primarily the customer''s responsibility ([ap-2.1-002]).', 61, 'm_61_1', 19, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is using Amazon S3 to store sensitive customer data. They want to ensure this data is encrypted at rest and that access to it is strictly controlled. According to the AWS shared responsibility model, which of the following is primarily the customer''s responsibility?', '["Managing the physical security of the data centers where Amazon S3 stores data.","Ensuring the underlying Amazon S3 infrastructure is patched and secure.","Configuring Amazon S3 bucket policies and enabling encryption for the data stored.","Maintaining the network infrastructure that supports Amazon S3 services."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is primarily the customer''s responsibility as part of ''security IN the cloud.'' For a managed service like Amazon S3, AWS is responsible for the security of the service itself, but the customer is responsible for the data they put into the service, including data encryption, access control (via bucket policies and IAM), and network configuration (e.g., VPC endpoints). Option A (incorrect) is AWS''s responsibility as part of ''security OF the cloud.'' Option B (incorrect) is AWS''s responsibility for the underlying infrastructure. Option D (incorrect) is AWS''s responsibility for the network infrastructure supporting the service ([ap-2.1-001]).', 61, 'm_61_1', 20, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is deploying a new application on Amazon EC2 instances. The application team is responsible for managing the operating system, application code, and network configurations. According to the AWS Shared Responsibility Model, which of the following is explicitly the customer''s responsibility for this EC2-based application?', '["Maintaining the physical security of the data centers where the EC2 instances reside.","Patching the underlying virtualization software (hypervisor) for the EC2 instances.","Ensuring the global network infrastructure that connects AWS Regions and Availability Zones is operational.","Configuring the security groups and network ACLs to control traffic to and from the EC2 instances."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is explicitly the customer''s responsibility under the AWS Shared Responsibility Model for IaaS services like Amazon EC2. Customers are responsible for security ''in'' the cloud, which includes configuring their own network controls such as security groups and network ACLs. Option A (incorrect) is an AWS responsibility, as AWS is responsible for the physical security of the data centers. Option B (incorrect) is also an AWS responsibility; AWS manages the security of the underlying virtualization software (hypervisor). Option C (incorrect) is an AWS responsibility, as AWS is responsible for the security and operational status of its global network infrastructure. These three options fall under ''security OF the cloud,'' which AWS manages.', 61, 'm_61_1', 21, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 21
WHERE id = 'mock_60_all_1775002619521';

COMMIT;

