INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A development team needs to deploy a new web application that requires a managed environment, where they can focus on their application code without managing the underlying servers, operating systems, or application stack. They want to minimize operational overhead for infrastructure management.', '["Deploy the application on Amazon EC2 instances and manually configure the web server.","Utilize AWS Elastic Beanstalk to deploy and manage the application.","Write AWS CloudFormation templates to provision EC2 instances, load balancers, and databases.","Deploy the application on Amazon Lightsail instances and manage the operating system manually."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) utilizes AWS Elastic Beanstalk, which is a Platform as a Service (PaaS) offering. It automatically handles the deployment, provisioning, load balancing, auto-scaling, and health monitoring of the application, allowing the development team to focus solely on their code, thus minimizing operational overhead. Option A (incorrect) requires manual management of EC2 instances, including OS patching and web server configuration, which increases operational overhead. Option C (incorrect) involves Infrastructure as Code (IaC) with AWS CloudFormation, which automates provisioning but still requires the team to define and manage the underlying resources and their configurations, which is more involved than Elastic Beanstalk for a managed application environment. Option D (incorrect) uses Amazon Lightsail, which simplifies VPS management but still requires manual operating system management and does not provide the same level of automated application environment management as Elastic Beanstalk.', 62, 'm_62_1', 1, NULL, NULL),
  ('mock_60_all_1775002619521', 'A small development team wants to quickly provision and manage their AWS infrastructure for a new project. They need a way to define their resources (EC2 instances, RDS databases, VPCs) in a declarative template that can be version-controlled and deployed consistently across environments.', '["Manually provision resources using the AWS Management Console for each environment.","Utilize AWS CloudFormation to define and deploy infrastructure as code.","Write custom scripts using the AWS CLI to create and configure resources.","Deploy the application using AWS Elastic Beanstalk for environment management."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) suggests using AWS CloudFormation, which allows defining AWS infrastructure in declarative templates (Infrastructure as Code). These templates can be version-controlled, enabling consistent and repeatable deployments across different environments, which is crucial for managing infrastructure at scale. Option A (incorrect) involves manual provisioning via the AWS Management Console, which is error-prone, not repeatable, and not auditable, especially for production environments. Option C (incorrect) uses custom AWS CLI scripts. While providing automation, CLI scripts are imperative, harder to maintain, and don''t inherently provide the declarative state management or rollback capabilities of CloudFormation. Option D (incorrect) uses AWS Elastic Beanstalk, which is a PaaS for deploying applications, but it''s not primarily designed for defining and managing arbitrary infrastructure resources like VPCs or complex database setups in a declarative, version-controlled manner.', 62, 'm_62_1', 2, NULL, NULL),
  ('mock_60_all_1775002619521', 'A software company wants to deploy a new microservices application using containers. They prefer a serverless approach for their container orchestration to avoid managing the underlying EC2 instances for their container hosts, thereby reducing operational burden.', '["Deploy containers using Amazon ECS on Amazon EC2 instances.","Utilize AWS Fargate as the compute engine for Amazon ECS.","Set up an Amazon EKS cluster and manage the Kubernetes control plane.","Provision Amazon Lightsail instances and manually deploy containers."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) recommends utilizing AWS Fargate as the compute engine for Amazon ECS. Fargate is a serverless compute engine for containers that removes the need to provision, configure, and scale clusters of virtual machines, significantly reducing operational burden by allowing the team to focus solely on defining their containerized applications. Option A (incorrect) uses Amazon ECS on Amazon EC2, which requires managing the underlying EC2 instances, including patching, scaling, and maintenance, increasing operational overhead. Option C (incorrect) involves Amazon EKS, which is a managed Kubernetes service. While EKS manages the Kubernetes control plane, it still typically requires managing the underlying EC2 worker nodes (unless Fargate is used with EKS, but the option doesn''t specify that). Option D (incorrect) suggests Amazon Lightsail, which is for simple VPS deployments and not designed for scalable container orchestration.', 62, 'm_62_1', 3, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A global e-commerce company wants to deliver static and dynamic content to its customers worldwide with the LOWEST possible latency. They also need to improve the security of their web application by filtering malicious traffic at the edge.', '["Host all content on Amazon S3 in a single AWS Region and use Amazon Route 53 for DNS resolution.","Deploy Amazon EC2 instances in multiple Availability Zones and use an Application Load Balancer.","Distribute content using Amazon CloudFront with AWS WAF enabled and an Amazon S3 origin.","Use AWS Global Accelerator to direct traffic to the closest Amazon EC2 instances in different Regions."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) leverages Amazon CloudFront, a Content Delivery Network (CDN), to cache content at edge locations globally, significantly reducing latency for users worldwide. Integrating AWS WAF with CloudFront provides protection against common web exploits. Option A (incorrect) would result in high latency for distant users as all requests would travel to a single S3 origin. Option B (incorrect) provides high availability within a Region but does not optimize global latency or provide edge security for content delivery. Option D (incorrect) uses AWS Global Accelerator to improve performance for non-cached content by directing traffic to optimal endpoints, but CloudFront is specifically designed for content delivery and caching, offering better latency for static/dynamic content and integrating directly with WAF for security at the edge.', 62, 'm_62_2', 4, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is planning to expand its online gaming platform globally. They need to choose an AWS Region for their new deployment that balances latency for their target audience, compliance requirements for data residency, and overall service availability.', '["Select the AWS Region that offers the lowest overall pricing for compute and storage.","Choose a Region that is geographically closest to the majority of their current users.","Select a Region that balances geographical proximity to users, adherence to data residency laws, and comprehensive service offerings.","Prioritize a Region with the highest number of Availability Zones, regardless of user location or compliance needs."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) describes a balanced approach to Region selection, considering geographical proximity to users (for low latency), adherence to data residency laws (for compliance), and comprehensive service offerings (for availability and functionality). This holistic view is essential for a global platform. Option A (incorrect) focuses solely on cost, which can lead to high latency for users and potential non-compliance with data residency regulations. Option B (incorrect) prioritizes geographical proximity, which is important for latency, but ignores critical factors like compliance and the full range of services available. Option D (incorrect) prioritizes the number of Availability Zones, which is important for high availability within a Region, but does not consider user latency, compliance, or specific service availability needs across different Regions.', 62, 'm_62_2', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_7
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A marketing department has a large collection of customer feedback in text format and needs to automatically extract key phrases, sentiment, and entities (like product names) to understand customer trends. They have limited machine learning expertise and want a fully managed service.', '["Use Amazon SageMaker to build, train, and deploy a custom NLP model.","Process the text data using AWS Glue for ETL and then analyze it manually.","Query the text data stored in Amazon S3 using Amazon Athena for keyword searches.","Utilize Amazon Comprehend to analyze the text data for sentiment, key phrases, and entities."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) utilizes Amazon Comprehend, a fully managed natural language processing (NLP) service that provides pre-trained models for tasks like sentiment analysis, key phrase extraction, and entity recognition. This requires no machine learning expertise and is highly efficient for the stated use case. Option A (incorrect) would require significant machine learning expertise to build, train, and deploy a custom model, which goes against the requirement of limited ML expertise. Option B (incorrect) focuses on ETL (Extract, Transform, Load) and would not automatically perform sentiment or entity analysis; manual analysis would be inefficient for large datasets. Option C (incorrect) allows querying data in S3 using SQL, which can be used for keyword searches, but it does not provide automated sentiment or entity extraction.', 62, 'm_62_7', 6, NULL, NULL),
  ('mock_60_all_1775002619521', 'A data analytics team needs to perform ad-hoc SQL queries on petabytes of log data stored in Amazon S3. They want a serverless solution that doesn''t require provisioning or managing any compute infrastructure and pays only for the data scanned.', '["Provision an Amazon EMR cluster to run Apache Spark for querying the data.","Load the data into an Amazon Redshift data warehouse for SQL querying.","Use AWS Glue to catalog the data and then query it with Amazon QuickSight.","Utilize Amazon Athena to run SQL queries directly on the data in Amazon S3."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) recommends Amazon Athena, a serverless query service that allows running standard SQL queries directly on data stored in Amazon S3. It requires no infrastructure provisioning or management, and users pay only for the data scanned by their queries, perfectly matching the requirements. Option A (incorrect) involves Amazon EMR, which requires provisioning and managing clusters, incurring operational overhead and continuous costs. Option B (incorrect) suggests Amazon Redshift, a data warehouse that requires provisioning and managing a cluster, which is not serverless and incurs continuous costs. Option C (incorrect) uses AWS Glue for cataloging and Amazon QuickSight for visualization. While Glue can catalog data, QuickSight is a BI service and not primarily for ad-hoc SQL querying on raw S3 data; Athena is the direct tool for that.', 62, 'm_62_7', 7, NULL, NULL),
  ('mock_60_all_1775002619521', 'A business analyst needs to create interactive dashboards and visualizations from various AWS data sources (e.g., Amazon RDS, Amazon S3, Amazon Athena) to monitor key performance indicators. They require a serverless Business Intelligence (BI) service that supports machine learning-powered insights.', '["Develop custom dashboards using a third-party BI tool hosted on Amazon EC2 instances.","Load all data into Amazon Redshift and use a traditional BI tool for visualization.","Utilize AWS Glue to prepare and catalog the data, then export it to a spreadsheet for manual charting.","Implement Amazon QuickSight to create interactive dashboards with ML-powered insights."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) suggests implementing Amazon QuickSight. QuickSight is a serverless Business Intelligence (BI) service that allows users to easily create interactive dashboards and visualizations from various AWS data sources. It includes ML-powered insights (e.g., anomaly detection, forecasting) and operates on a pay-per-session model, aligning with the serverless and ML-powered insights requirements. Option A (incorrect) involves developing custom dashboards on EC2, which increases operational overhead for server management and maintenance, and may not inherently provide ML-powered insights. Option B (incorrect) uses Amazon Redshift, which is a data warehouse, not a BI visualization tool. While data can be loaded into Redshift, a separate BI tool would still be needed, and Redshift itself is not serverless. Option C (incorrect) uses AWS Glue for data preparation, but exporting to a spreadsheet for manual charting is inefficient, not interactive, and lacks ML-powered insights.', 62, 'm_62_7', 8, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company runs a batch processing workload that can tolerate interruptions and needs to be highly cost-effective. The workload processes large datasets overnight and can restart from checkpoints if an instance is terminated.', '["Launch Amazon EC2 Spot Instances for the batch processing jobs.","Provision Amazon EC2 On-Demand Instances to ensure consistent processing.","Purchase Amazon EC2 Reserved Instances for a fixed capacity over a long term.","Use AWS Lambda functions to process the large datasets in parallel."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) suggests launching Amazon EC2 Spot Instances. Spot Instances offer significant cost savings (up to 90% compared to On-Demand) and are ideal for fault-tolerant, flexible workloads like batch processing that can tolerate interruptions and restart from checkpoints. Option B (incorrect) uses On-Demand Instances, which are more expensive and not necessary for a workload that can tolerate interruptions. Option C (incorrect) involves Reserved Instances, which are suitable for steady-state, predictable workloads over a long term, not for interruptible batch jobs. Option D (incorrect) uses AWS Lambda, which is serverless and cost-effective for event-driven, short-duration tasks, but might not be suitable or cost-effective for processing large datasets that require long-running compute or specific instance types, and has execution duration limits.', 62, 'm_62_3', 9, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company''s web application experiences highly variable traffic, with significant spikes during promotional events. They need to automatically adjust their compute capacity to match demand, ensuring performance during peak loads while minimizing costs during low usage periods.', '["Implement Amazon EC2 Auto Scaling to automatically adjust instance count.","Manually add or remove Amazon EC2 instances based on anticipated traffic patterns.","Provision a fixed number of large Amazon EC2 instances to handle peak capacity.","Migrate the entire application to AWS Lambda to handle all traffic spikes."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) recommends implementing Amazon EC2 Auto Scaling. This service automatically adjusts the number of EC2 instances in an Auto Scaling group based on defined policies (e.g., CPU utilization, network I/O), ensuring the application maintains performance during traffic spikes and scales down during low usage to minimize costs. Option B (incorrect) involves manual scaling, which is slow, error-prone, and cannot react quickly enough to sudden traffic changes, leading to either over-provisioning or performance issues. Option C (incorrect) suggests provisioning a fixed number of large instances, which would lead to significant over-provisioning and wasted costs during off-peak hours. Option D (incorrect) proposes migrating to AWS Lambda. While Lambda is serverless and scales automatically, migrating an entire web application might be a significant architectural change and not always feasible or optimal for all types of web applications, especially those with long-running connections or specific runtime requirements.', 62, 'm_62_3', 10, NULL, NULL),
  ('mock_60_all_1775002619521', 'A data processing application requires significant computational power for short, intensive bursts of activity, followed by long periods of inactivity. The company wants to pay only for the compute time consumed during processing.', '["Use AWS Lambda for event-driven, serverless compute.","Provision Amazon EC2 On-Demand Instances and keep them running 24/7.","Purchase Amazon EC2 Reserved Instances for the expected burst capacity.","Utilize Amazon EC2 Spot Instances for the short, intensive bursts."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) recommends AWS Lambda. Lambda is a serverless compute service where you pay only for the compute time consumed (per invocation and duration), making it ideal for sporadic, bursty workloads with long periods of inactivity. It automatically scales and requires no server management. Option B (incorrect) involves provisioning On-Demand EC2 instances and running them 24/7, which would incur costs even during inactive periods, violating the ''pay only for compute time consumed'' constraint. Option C (incorrect) suggests Reserved Instances, which are for predictable, steady-state workloads and would not be cost-effective for bursty, intermittent usage. Option D (incorrect) uses Amazon EC2 Spot Instances. While cost-effective for interruptible workloads, they still involve managing EC2 instances and are not truly ''pay only for compute time consumed'' in the serverless sense, as you pay for the instance''s uptime until it''s interrupted or stopped.', 62, 'm_62_3', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_4
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A startup is building a new mobile application that requires a highly scalable, non-relational database to store user profiles and game scores. The data model is flexible, and they anticipate rapid growth with unpredictable access patterns, requiring single-digit millisecond latency.', '["Provision an Amazon RDS for MySQL instance with a large storage capacity.","Utilize Amazon DynamoDB for its key-value and document data model capabilities.","Deploy an Amazon Aurora PostgreSQL-compatible cluster with multiple read replicas.","Set up an Amazon Redshift cluster for data warehousing and analytical queries."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) recommends Amazon DynamoDB, a fully managed NoSQL database service that provides single-digit millisecond performance at any scale. It is ideal for flexible data models, high scalability, and unpredictable access patterns, making it perfect for user profiles and game scores in a mobile application. Option A (incorrect) uses Amazon RDS for MySQL, which is a relational database. While scalable, it enforces a rigid schema and may not offer the same level of flexibility or performance for rapidly growing, non-relational data with unpredictable access patterns. Option C (incorrect) uses Amazon Aurora, a high-performance relational database. Similar to RDS, it''s not optimized for flexible NoSQL data models. Option D (incorrect) suggests Amazon Redshift, which is a data warehouse service optimized for complex analytical queries, not for transactional, low-latency storage of application data.', 62, 'm_62_4', 12, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company is migrating its existing MySQL database from on-premises to AWS. They want a managed relational database service that handles patching, backups, and replication automatically, allowing their team to focus on application development.', '["Install MySQL on an Amazon EC2 instance and manage it manually.","Migrate the database to Amazon RDS for MySQL.","Use Amazon DynamoDB for its NoSQL capabilities.","Set up an Amazon Redshift cluster for data warehousing."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is to migrate the database to Amazon RDS for MySQL. Amazon RDS is a fully managed relational database service that automates administrative tasks like patching, backups, and replication, significantly reducing operational overhead and allowing the team to focus on application development. Option A (incorrect) involves installing MySQL on an Amazon EC2 instance, which would require the company to manually manage all database administration tasks, including patching, backups, and high availability, defeating the purpose of minimizing operational burden. Option C (incorrect) suggests Amazon DynamoDB, which is a NoSQL database and not suitable for migrating an existing relational MySQL database without a significant re-architecture of the application. Option D (incorrect) proposes Amazon Redshift, which is a data warehousing service optimized for analytics, not for transactional relational databases.', 62, 'm_62_4', 13, NULL, NULL),
  ('mock_60_all_1775002619521', 'A web application experiences heavy read traffic, especially during peak hours. The primary database, an Amazon RDS for MySQL instance, is becoming a bottleneck. The company needs to improve read performance and offload read requests from the primary database.', '["Scale up the primary Amazon RDS instance to a larger instance type.","Implement Amazon RDS Read Replicas to distribute read traffic.","Migrate the database to Amazon DynamoDB for its NoSQL capabilities.","Self-manage a caching layer on an Amazon EC2 instance in front of the database."]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) suggests implementing Amazon RDS Read Replicas. Read Replicas provide an excellent solution for read-heavy workloads by allowing you to offload read traffic from the primary database instance to one or more replicas. This improves read performance and reduces the load on the primary instance. Option A (incorrect) involves scaling up the primary RDS instance. While this might provide a temporary improvement, it''s a vertical scaling approach that has limits and can be more expensive than horizontal scaling with read replicas for read-heavy workloads. Option C (incorrect) proposes migrating to Amazon DynamoDB. This is a NoSQL database and would require a significant re-architecture of the application and data model, which is not the most direct solution for offloading read traffic from an existing relational database. Option D (incorrect) suggests self-managing a caching layer on an Amazon EC2 instance. While caching can improve performance, self-managing it increases operational overhead, whereas Amazon ElastiCache (a managed caching service) or RDS Read Replicas are managed solutions.', 62, 'm_62_4', 14, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_5
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company needs to establish a secure and private connection between its on-premises data center and its Amazon VPC to access applications hosted in AWS. The connection must support high bandwidth and consistent network performance for critical business applications.', '["Configure an AWS Site-to-Site VPN connection over the public internet.","Utilize an Internet Gateway to route traffic between on-premises and the VPC.","Establish an AWS Direct Connect connection for a dedicated private network.","Set up VPC peering between the on-premises network and the Amazon VPC."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) recommends AWS Direct Connect. It provides a dedicated, private network connection from your on-premises data center to AWS, offering consistent network performance and high bandwidth, which is crucial for critical business applications. Option A (incorrect) uses an AWS Site-to-Site VPN, which establishes an encrypted connection over the public internet. While secure, its performance can be variable and is subject to internet congestion, making it less suitable for high-bandwidth and consistent performance requirements. Option B (incorrect) uses an Internet Gateway, which provides public internet access and does not create a private connection to an on-premises data center. Option D (incorrect) involves VPC peering, which connects two VPCs within AWS, not an on-premises network to a VPC.', 62, 'm_62_5', 15, NULL, NULL),
  ('mock_60_all_1775002619521', 'A security-conscious organization needs to ensure that its application servers, which are running in an Amazon VPC, can initiate outbound connections to the internet for software updates but are not directly accessible from the internet.', '["Place the application servers in a public subnet and attach an Internet Gateway.","Place the application servers in a private subnet and configure a Security Group to allow outbound traffic.","Place the application servers in a private subnet and route outbound traffic through a NAT Gateway.","Configure a Network ACL to allow all outbound traffic and deny all inbound traffic to the public subnet."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to place the application servers in a private subnet and route outbound traffic through a NAT Gateway. Resources in a private subnet are not directly accessible from the internet. A NAT Gateway allows instances in private subnets to connect to the internet for updates or patches while preventing unsolicited inbound connections from the internet. Option A (incorrect) places servers in a public subnet, making them directly accessible from the internet, which violates the security requirement of not being directly accessible. Option B (incorrect) configures a Security Group, which controls traffic to/from instances. While necessary, a Security Group alone does not provide outbound internet access from a private subnet without a NAT Gateway or similar mechanism. Option D (incorrect) configures a Network ACL, which operates at the subnet level and is stateless. While it can deny inbound traffic, simply allowing outbound traffic from a public subnet still exposes the servers to the internet.', 62, 'm_62_5', 16, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to host a static website on AWS. They want a highly available and cost-effective solution that can serve content directly from object storage.', '["Provision an Amazon EC2 instance and install a web server like Apache or Nginx.","Use Amazon Lightsail with a pre-configured content management system (CMS).","Host the static website directly from an Amazon S3 bucket configured for static website hosting.","Deploy an Amazon CloudFront distribution with an Amazon EC2 instance as the origin."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is to host the static website directly from an Amazon S3 bucket configured for static website hosting. This is a highly available, durable, and extremely cost-effective solution for static content, as S3 is designed for 99.999999999% (11 nines) durability and is serverless, eliminating compute costs. Option A (incorrect) involves provisioning an Amazon EC2 instance, which incurs compute costs and requires managing the web server, increasing operational overhead compared to S3 static website hosting. Option B (incorrect) uses Amazon Lightsail, which is a simplified virtual private server (VPS) service. While easy to set up, it''s not as cost-effective or serverless as S3 for static content and still involves managing a server. Option D (incorrect) uses Amazon CloudFront with an EC2 instance as the origin. While CloudFront improves global performance, using an EC2 instance as the origin for a static site is more complex and costly than simply using an S3 bucket as the origin.', 62, 'm_62_5', 17, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_6
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A media company stores large video files that are frequently accessed for the first 30 days after upload, then become infrequently accessed but must be immediately available for up to a year, and finally need to be archived for compliance for 7 years with infrequent retrieval. They want to minimize storage costs.', '["Store all video files in Amazon S3 Standard for the entire 8-year period.","Manually move files from Amazon S3 Standard to S3 Standard-IA after 30 days, then to S3 Glacier after 1 year.","Use Amazon S3 Standard-IA for the first year, then transition to Amazon S3 Glacier Deep Archive.","Implement Amazon S3 Intelligent-Tiering with lifecycle policies to move data to Amazon S3 Glacier Deep Archive."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) suggests implementing Amazon S3 Intelligent-Tiering, which automatically moves objects between access tiers (Frequent Access, Infrequent Access, Archive Instant Access) based on changing access patterns, without performance impact. Combined with lifecycle policies, it can automatically transition data to Amazon S3 Glacier Deep Archive for long-term, cost-effective archiving after a year, minimizing storage costs. Option A (incorrect) would be very expensive as S3 Standard is for frequently accessed data and not cost-optimized for infrequent access or archival. Option B (incorrect) involves manual intervention, which is prone to errors and increases operational overhead, failing the goal of minimizing costs efficiently. Option C (incorrect) uses S3 Standard-IA for the first year, which is suitable for infrequent access but doesn''t account for the initial frequent access period and would be more expensive than Intelligent-Tiering for the first 30 days, and also doesn''t leverage automatic tiering.', 62, 'm_62_6', 18, NULL, NULL),
  ('mock_60_all_1775002619521', 'A team of data scientists needs a shared file system that can be mounted by multiple Amazon EC2 instances simultaneously. The file system must support the Network File System (NFS) protocol and automatically scale to petabytes of data without manual intervention.', '["Attach Amazon EBS volumes to each individual EC2 instance.","Store the data in Amazon S3 buckets and access it via the S3 API.","Utilize Amazon FSx for Windows File Server for shared access.","Implement Amazon EFS for a scalable, shared file system."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) recommends Amazon EFS (Elastic File System). EFS provides a scalable, shared file system that can be mounted by thousands of Amazon EC2 instances simultaneously using the NFS protocol. It automatically scales to petabytes of data without manual intervention, perfectly meeting the requirements. Option A (incorrect) suggests Amazon EBS volumes. EBS volumes are block storage and can typically only be attached to a single EC2 instance at a time (with Multi-Attach as an exception for io1/io2, but not for general shared file system needs via NFS). Option B (incorrect) involves Amazon S3, which is object storage. While highly scalable, it''s accessed via an API, not mounted as a file system using NFS, and would require application changes to interact with objects. Option C (incorrect) uses Amazon FSx for Windows File Server, which provides a fully managed native Microsoft Windows file system. While shared, it''s designed for Windows workloads and CIFS protocol, not NFS for Linux-based EC2 instances typically used by data scientists.', 62, 'm_62_6', 19, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to migrate 500 terabytes of archival data from its on-premises data center to Amazon S3 Glacier Deep Archive. Transferring this volume of data over the internet would take too long and be unreliable.', '["Use AWS Storage Gateway to create a hybrid cloud storage solution.","Establish an AWS Direct Connect connection to transfer the data.","Transfer the data over the internet using the AWS CLI and multi-part uploads.","Utilize AWS Snowball to physically ship the data to AWS."]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) recommends utilizing AWS Snowball. AWS Snowball is part of the AWS Snow Family, which provides physical devices for transferring large amounts of data (petabytes) into and out of AWS. For 500 terabytes, Snowball is a highly efficient and reliable method, significantly faster than transferring over the internet. Option A (incorrect) suggests AWS Storage Gateway, which is designed for hybrid cloud storage, allowing on-premises applications to use cloud storage. While it can synchronize data, it''s not primarily for a one-time, large-scale offline migration. Option B (incorrect) involves AWS Direct Connect, which provides a dedicated network connection. While it offers high bandwidth and consistent performance, the setup time and cost for a one-time archival migration of this size might be less optimal than Snowball. Option C (incorrect) proposes transferring data over the internet using the AWS CLI. For 500 terabytes, this would be extremely time-consuming, unreliable, and potentially costly due to egress charges from the on-premises network.', 62, 'm_62_6', 20, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_62_8
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A company wants to send real-time notifications to its mobile application users whenever a new product is launched or a critical system alert occurs. They need a fully managed service that can reliably deliver messages to a large number of subscribers.', '["Use Amazon SNS to publish messages to topics that mobile devices subscribe to.","Implement Amazon SQS queues for each mobile device to receive notifications.","Orchestrate message delivery using AWS Step Functions for each notification.","Store notification messages in Amazon S3 and have mobile apps poll for new files."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses Amazon SNS (Simple Notification Service), a fully managed pub/sub messaging service. It allows publishing messages to topics, which can then be subscribed to by a large number of endpoints, including mobile devices, for real-time notifications. Option B (incorrect) suggests Amazon SQS (Simple Queue Service). While SQS is a messaging service, it''s designed for decoupling microservices and is a pull-based model (consumers poll the queue), not ideal for real-time push notifications to many subscribers. Option C (incorrect) involves AWS Step Functions, which is a serverless workflow orchestration service. It''s overkill and not designed for simple, real-time fan-out notifications. Option D (incorrect) would require mobile applications to constantly poll Amazon S3, which is inefficient, costly, and not real-time for notifications.', 62, 'm_62_8', 21, NULL, NULL),
  ('mock_60_all_1775002619521', 'A company needs to process a high volume of streaming data from IoT devices in real-time for immediate analytics and dashboard updates. The solution must be able to handle fluctuating data ingestion rates and integrate with other analytics services.', '["Use Amazon Kinesis Data Streams for real-time data ingestion and processing.","Store the streaming data in Amazon S3 and process it with daily batch jobs.","Utilize Amazon SQS to queue messages for later processing by a single consumer.","Implement AWS Batch to run scheduled processing jobs on the collected data."]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) uses Amazon Kinesis Data Streams, which is designed for real-time processing of large streams of data. It can handle high ingestion rates, allows multiple consumers to process data concurrently, and integrates well with other analytics services for immediate insights. Option B (incorrect) suggests storing data in Amazon S3 and processing it daily. This is a batch approach and would not provide real-time analytics or immediate dashboard updates. Option C (incorrect) involves Amazon SQS. While SQS is a messaging queue, it''s typically used for decoupling components and asynchronous processing, not for high-volume, real-time streaming data ingestion with multiple concurrent consumers. Option D (incorrect) recommends AWS Batch, which is a service for running batch computing workloads. This is not suitable for real-time streaming data processing.', 62, 'm_62_8', 22, NULL, NULL),
  ('mock_60_all_1775002619521', 'A development team needs to build a serverless workflow that orchestrates multiple AWS Lambda functions and other AWS services in a specific sequence, handling retries, parallel execution, and error handling.', '["Use Amazon SQS to queue messages between Lambda functions for sequential processing.","Implement Amazon SNS to publish events that trigger multiple Lambda functions.","Utilize AWS Step Functions to define and orchestrate the serverless workflow.","Write custom code within an AWS Lambda function to call other Lambda functions sequentially."]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) recommends utilizing AWS Step Functions. Step Functions is a serverless workflow service that allows you to define complex workflows as state machines, orchestrating multiple AWS Lambda functions and other AWS services. It natively handles sequencing, parallel execution, error handling, retries, and state management, making it ideal for complex serverless workflows. Option A (incorrect) suggests Amazon SQS, which is a message queuing service. While it can decouple services, it''s not designed for orchestrating complex sequences, managing state, or handling retries and error logic within a workflow. Option B (incorrect) involves Amazon SNS, a pub/sub messaging service. It''s suitable for fanning out events to multiple subscribers but lacks the orchestration capabilities for sequential execution, state management, or complex error handling. Option D (incorrect) proposes writing custom code within a Lambda function to call other Lambda functions. This approach quickly becomes complex, hard to maintain, and lacks built-in features for retries, error handling, and visual workflow monitoring that Step Functions provides.', 62, 'm_62_8', 23, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 23
WHERE id = 'mock_60_all_1775002619521';

COMMIT;

