INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A media company needs to process large volumes of video transcoding jobs. These jobs are fault-tolerant and can be interrupted and resumed without significant loss of progress. The company''s primary goal is to minimize compute costs for these non-critical, flexible workloads. Which EC2 pricing model should be recommended to achieve the MOST cost-effective solution?', '["Amazon EC2 Spot Instances","Amazon EC2 On-Demand Instances","Amazon EC2 Reserved Instances","Amazon EC2 Dedicated Hosts"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) recommends Amazon EC2 Spot Instances. Spot Instances allow users to bid on unused EC2 capacity, offering up to a 90% discount compared to On-Demand prices. They are ideal for fault-tolerant, flexible workloads like video transcoding that can tolerate interruptions, making them the most cost-effective choice for this scenario (anti-pattern ap-4.1-005). Option B (incorrect) refers to Amazon EC2 On-Demand Instances, which are the most expensive option and offer no long-term commitment or significant discounts, making them unsuitable for cost minimization. Option C (incorrect) refers to Amazon EC2 Reserved Instances, which provide significant discounts for a 1- or 3-year commitment. While cost-effective for steady-state workloads, they are not ideal for interruptible or unpredictable tasks, and the commitment is not flexible enough for jobs that can be stopped and restarted (anti-pattern ap-4.1-003). Option D (incorrect) refers to Amazon EC2 Dedicated Hosts, which provide physical servers dedicated to your use. This option is primarily for licensing requirements or strict compliance and is significantly more expensive than other options, offering no cost savings for flexible batch processing.', 63, 'm_63_1', 1, NULL, NULL),
  ('mock_60_all_1775002619521', 'A software development firm plans to run a core application on Amazon EC2 instances that requires a consistent, predictable compute capacity for the next three years. The application workload is steady-state and does not fluctuate significantly. The finance team''s main objective is to MINIMIZE the total cost of ownership over this long-term period. Which pricing model should they choose?', '["Amazon EC2 On-Demand Instances","Amazon EC2 Reserved Instances","Amazon EC2 Spot Instances","AWS Free Tier"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) recommends Amazon EC2 Reserved Instances. For a predictable, steady-state workload over a 3-year period, Reserved Instances offer significant discounts (up to 72%) compared to On-Demand pricing in exchange for a commitment. This directly addresses the goal of minimizing total cost of ownership over the long term (anti-pattern ap-4.1-002). Option A (incorrect) refers to Amazon EC2 On-Demand Instances, which are the most expensive pricing option and do not provide any long-term cost savings for predictable workloads. Option C (incorrect) refers to Amazon EC2 Spot Instances, which offer deep discounts but are interruptible and best suited for fault-tolerant, flexible workloads, not consistent, steady-state applications. Option D (incorrect) refers to the AWS Free Tier, which is designed for new users to explore services for free for a limited period or up to certain usage limits. It is not a sustainable pricing model for a core production application with consistent, long-term usage.', 63, 'm_63_1', 2, NULL, NULL),
  ('mock_60_all_1775002619521', 'A global company operates an application in the `us-east-1` AWS Region and needs to replicate large datasets to `eu-west-1` for disaster recovery purposes. The company is concerned about the recurring monthly costs associated with transferring this data. Which factor is MOST critical to consider when estimating and minimizing the data transfer costs for this cross-Region replication?', '["The number of Amazon EC2 instances running in the destination Region.","The storage class of Amazon S3 buckets in the source Region.","The volume of data transferred out of the source Region to the destination Region.","The type of AWS Support plan subscribed to for the account."]'::jsonb, 'mcq', '{3}'::integer[], 'Option C (correct) identifies the volume of data transferred out of the source Region to the destination Region as the most critical factor. AWS charges for data transfer out of a Region and between different Regions. The larger the volume of data replicated from `us-east-1` to `eu-west-1`, the higher the data transfer costs will be. This is a common oversight when estimating total cloud costs (anti-pattern ap-4.1-004). Option A (incorrect) refers to the number of Amazon EC2 instances in the destination Region, which primarily impacts compute costs, not data transfer costs between Regions. Option B (incorrect) refers to the storage class of Amazon S3 buckets in the source Region, which impacts storage costs and retrieval costs, but not the cost of data transfer out of the Region itself. Option D (incorrect) refers to the AWS Support plan, which impacts the cost of support services but has no direct bearing on data transfer costs.', 63, 'm_63_1', 3, NULL, NULL),
  ('mock_60_all_1775002619521', 'A small e-commerce business experiences highly variable customer traffic, with significant spikes during promotional events and very low activity otherwise. They want to host their backend API using a serverless compute service to automatically scale with demand and only pay for actual usage, while keeping costs low during idle periods. Which AWS service and pricing model best fits this requirement?', '["AWS Lambda with a pay-per-invocation and duration model","Amazon EC2 On-Demand Instances with auto scaling","Amazon EC2 Reserved Instances with a 1-year commitment","Amazon EC2 Spot Instances for the entire API backend"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) recommends AWS Lambda with its pay-per-invocation and duration model. AWS Lambda is a serverless compute service that automatically scales with demand and charges only for the number of requests and the compute time consumed, making it ideal for highly variable workloads where costs need to be low during idle periods. Option B (incorrect) suggests Amazon EC2 On-Demand Instances with auto scaling. While auto scaling helps with variable traffic, On-Demand EC2 instances still incur costs even when idle if they are running, and they require managing servers, increasing operational overhead compared to serverless. Option C (incorrect) suggests Amazon EC2 Reserved Instances. Reserved Instances require a commitment and are best for predictable, steady-state workloads, not highly variable ones (anti-pattern ap-4.1-003). Option D (incorrect) suggests Amazon EC2 Spot Instances. Spot Instances are interruptible and are not suitable for a backend API that requires continuous availability and cannot tolerate unexpected interruptions.', 63, 'm_63_1', 4, NULL, NULL),
  ('mock_60_all_1775002619521', 'A research institution needs to store petabytes of scientific data that is rarely accessed but must be retained for compliance for many years. The data can tolerate retrieval times of several hours, and the primary concern is to achieve the LOWEST possible storage cost. Which Amazon S3 storage class is most appropriate for this requirement?', '["Amazon S3 Standard","Amazon S3 Standard-IA","Amazon S3 Glacier Deep Archive","Amazon S3 One Zone-IA"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is Amazon S3 Glacier Deep Archive. This storage class is designed for long-term archiving and offers the lowest cost storage in the cloud, with retrieval times ranging from 12 to 48 hours. This perfectly matches the requirement for rarely accessed data, long retention, and the lowest possible storage cost. Option A (incorrect) is Amazon S3 Standard, which is designed for frequently accessed data with high throughput and low latency, making it significantly more expensive than archiving solutions. Option B (incorrect) is Amazon S3 Standard-IA (Infrequent Access), which is suitable for data accessed less frequently but still requires rapid access when needed (milliseconds). It is more cost-effective than S3 Standard but not as cheap as Glacier Deep Archive for long-term archives. Option D (incorrect) is Amazon S3 One Zone-IA, which is similar to Standard-IA but stores data in a single Availability Zone, offering lower cost but reduced availability and durability compared to multi-AZ options, and still not as cheap as Glacier Deep Archive for deep archiving.', 63, 'm_63_1', 5, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_63_2
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A startup is concerned about controlling their AWS spending and wants to avoid unexpected high bills. They need a mechanism to proactively monitor their costs and receive alerts if their projected or actual spending exceeds predefined thresholds. Which AWS service should they configure to achieve this goal?', '["AWS Cost Explorer","AWS Budgets","AWS Cost and Usage Report","AWS Billing Dashboard"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is AWS Budgets. AWS Budgets allows users to set custom cost and usage thresholds and receive alerts when actual or forecasted costs exceed these thresholds. This provides a proactive mechanism to prevent unexpected charges and manage spending effectively (anti-pattern ap-4.2-001). Option A (incorrect) is AWS Cost Explorer, which is used for visualizing and analyzing historical spending patterns. While useful for identifying trends, it does not provide proactive alerts based on predefined thresholds. Option C (incorrect) is the AWS Cost and Usage Report, which provides highly detailed, line-item billing data. It is excellent for granular analysis and auditing but does not offer real-time alerts for exceeding budget thresholds. Option D (incorrect) is the AWS Billing Dashboard, which provides an overview of current month''s spending and payment information but lacks the proactive alerting capabilities of AWS Budgets.', 63, 'm_63_2', 6, NULL, NULL),
  ('mock_60_all_1775002619521', 'A finance department needs to understand the historical spending patterns of their AWS resources over the past year to identify areas for cost optimization. They require a tool that can visualize cost and usage data, allowing them to analyze trends, forecast future costs, and identify potential savings. Which AWS service is best suited for this analytical task?', '["AWS Budgets","AWS Billing Dashboard","AWS Cost and Usage Report","AWS Cost Explorer"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is AWS Cost Explorer. AWS Cost Explorer is a powerful tool that allows users to visualize, understand, and manage their AWS costs and usage over time. It provides historical data analysis, forecasting capabilities, and helps identify spending trends and savings opportunities (anti-pattern ap-4.2-003). Option A (incorrect) is AWS Budgets, which is used for setting proactive alerts on cost and usage thresholds, not for historical visualization and analysis. Option B (incorrect) is the AWS Billing Dashboard, which provides a high-level overview of current charges and payment information, but not detailed historical analysis or forecasting. Option C (incorrect) is the AWS Cost and Usage Report, which provides extremely granular line-item data. While it contains all the data, it requires external tools or significant effort to process and visualize, unlike the built-in visualization of Cost Explorer.', 63, 'm_63_2', 7, NULL, NULL),
  ('mock_60_all_1775002619521', 'A large enterprise uses AWS for multiple projects and departments. The accounting team needs to accurately allocate AWS costs to specific internal projects, teams, and environments (e.g., ''development'', ''staging'', ''production'') for chargeback purposes. Which AWS feature should be implemented to enable this granular cost attribution?', '["Cost allocation tags","AWS Cost Explorer reports","AWS Budgets alerts","AWS Organizations consolidated billing"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is Cost allocation tags. Cost allocation tags are labels (key-value pairs) that can be applied to AWS resources. Once activated, AWS uses these tags to organize costs on the cost allocation report, allowing the accounting team to track and attribute costs to specific projects, teams, or environments (anti-pattern ap-4.2-002). Option B (incorrect) refers to AWS Cost Explorer reports, which can visualize costs, but without proper tagging, it cannot break down costs by specific internal projects or teams. Option C (incorrect) refers to AWS Budgets alerts, which are used for proactive cost monitoring and notifications, not for granular cost attribution. Option D (incorrect) refers to AWS Organizations consolidated billing, which aggregates billing for multiple accounts but does not, by itself, provide the granular project-level cost attribution needed within an account.', 63, 'm_63_2', 8, NULL, NULL),
  ('mock_60_all_1775002619521', 'A growing company has recently expanded its AWS footprint to include several new departments, each with its own AWS account. The finance department wants to simplify billing management, gain a holistic view of spending across all accounts, and potentially benefit from volume discounts. Which AWS service should be used to achieve these objectives?', '["AWS Cost Explorer","AWS Budgets","AWS Organizations consolidated billing","AWS Billing Dashboard"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Organizations consolidated billing. Consolidated billing allows multiple AWS accounts to be grouped into an organization, receiving a single bill for all accounts. This simplifies billing management, provides a centralized view of spending, and enables accounts to benefit from volume pricing discounts, which are applied across the aggregated usage (anti-pattern ap-4.2-004). Option A (incorrect) is AWS Cost Explorer, which visualizes and analyzes costs, but does not consolidate billing or provide volume discounts across separate accounts. Option B (incorrect) is AWS Budgets, which sets alerts for cost thresholds, but does not manage multi-account billing. Option D (incorrect) is the AWS Billing Dashboard, which provides an overview for a single account or the master account in an organization, but doesn''t inherently simplify the management of multiple separate bills or apply volume discounts across them without Organizations.', 63, 'm_63_2', 9, NULL, NULL),
  ('mock_60_all_1775002619521', 'A data analytics team requires highly detailed, granular data about their AWS usage and costs for in-depth financial analysis and compliance auditing. They need access to every line item of their billing information, including resource IDs, usage types, and pricing details. Which AWS resource provides this level of comprehensive billing data?', '["AWS Billing Dashboard","AWS Cost and Usage Report","AWS Cost Explorer","AWS Budgets"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the AWS Cost and Usage Report (CUR). The CUR provides the most comprehensive set of AWS cost and usage data available, including line items for every charge, resource IDs, usage types, and pricing. It is ideal for detailed financial analysis, compliance auditing, and integrating with third-party cost management tools. Option A (incorrect) is the AWS Billing Dashboard, which offers a high-level summary of current charges but lacks the granular detail required for in-depth analysis. Option C (incorrect) is AWS Cost Explorer, which provides aggregated and visualized cost data, but the raw, line-item detail is not as extensive as in the CUR. Option D (incorrect) is AWS Budgets, which is used for setting alerts on cost thresholds, not for providing detailed billing records.', 63, 'm_63_2', 10, NULL, NULL),
  ('mock_60_all_1775002619521', 'A development team wants to quickly check their current month''s AWS charges and see a summary of their spending across different services. They need a simple, centralized view without diving into detailed reports or complex analysis tools. Which AWS resource offers this immediate, high-level overview?', '["AWS Cost Explorer","AWS Cost and Usage Report","AWS Budgets","AWS Billing Dashboard"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the AWS Billing Dashboard. The AWS Billing Dashboard provides a high-level overview of your current month''s AWS spending, recent invoices, and payment history. It''s designed for a quick glance at your account''s financial status without requiring deep analysis. Option A (incorrect) is AWS Cost Explorer, which is for detailed historical analysis and forecasting, not a quick summary. Option B (incorrect) is the AWS Cost and Usage Report, which provides extremely granular line-item data that requires significant processing to get a summary. Option C (incorrect) is AWS Budgets, which is used for setting cost alerts and notifications, not for displaying a general overview of current charges.', 63, 'm_63_2', 11, NULL, NULL);

-- ─────────────────────────────────────────
-- Module: m_63_3
-- ─────────────────────────────────────────

INSERT INTO public.mock_test_questions (mock_test_id, question_text, options, question_type, correct_answer, explanation, topic_id, module_id, question_order, pairs, matches)
VALUES
  ('mock_60_all_1775002619521', 'A cloud administrator wants to proactively identify potential cost savings, security vulnerabilities, and performance improvements within their AWS environment. They need an automated tool that provides real-time guidance based on AWS best practices across various categories. Which AWS service should they utilize for these recommendations?', '["AWS Health Dashboard","AWS Support Center","AWS Trusted Advisor","AWS Cost Explorer"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is AWS Trusted Advisor. AWS Trusted Advisor is an online tool that provides real-time guidance to help provision resources following AWS best practices. It inspects your AWS environment and makes recommendations in five categories: cost optimization, security, fault tolerance, performance, and service limits (anti-pattern ap-4.3-002). Option A (incorrect) is the AWS Health Dashboard, which provides personalized alerts about AWS service events that may affect your resources, not proactive best practice recommendations for your configuration. Option B (incorrect) is the AWS Support Center, which is where you create and manage support cases, not a tool for automated best practice recommendations. Option D (incorrect) is AWS Cost Explorer, which visualizes and analyzes historical spending patterns, but does not provide specific best practice recommendations for security or performance.', 63, 'm_63_3', 12, NULL, NULL),
  ('mock_60_all_1775002619521', 'An operations team needs to stay informed about any AWS service events, such as outages or scheduled maintenance, that might impact their specific resources. They require a personalized view of the health and status of the AWS services they are using. Which AWS resource provides these tailored notifications?', '["AWS Service Health Dashboard (global status page)","AWS Health Dashboard","AWS Trusted Advisor","AWS re:Post"]'::jsonb, 'mcq', '{1}'::integer[], 'Option B (correct) is the AWS Health Dashboard. The AWS Health Dashboard provides a personalized view of the health of AWS services and resources that are relevant to your specific account. It delivers proactive notifications about service events, scheduled activities, and performance issues that may affect your resources (anti-pattern ap-4.3-003). Option A (incorrect) is the AWS Service Health Dashboard, which provides a global view of the status of all AWS services across all regions, but it is not personalized to your account''s specific resources. Option C (incorrect) is AWS Trusted Advisor, which provides best practice recommendations for cost, security, performance, and fault tolerance, not real-time service health notifications. Option D (incorrect) is AWS re:Post, which is a community-driven Q&A service for technical questions, not a service health notification tool.', 63, 'm_63_3', 13, NULL, NULL),
  ('mock_60_all_1775002619521', 'A large enterprise with complex AWS environments requires proactive architectural guidance, operational reviews, and a dedicated point of contact for strategic planning and issue resolution. They need a Technical Account Manager (TAM) to help them optimize their AWS usage and ensure operational excellence. Which AWS Support plan includes a dedicated TAM?', '["Basic Support plan","Developer Support plan","Business Support plan","Enterprise On-Ramp Support plan"]'::jsonb, 'mcq', '{3}'::integer[], 'Option D (correct) is the Enterprise On-Ramp Support plan (or the full Enterprise Support plan). A dedicated Technical Account Manager (TAM) is a key feature of the Enterprise On-Ramp and Enterprise Support plans, providing proactive guidance, architectural reviews, and a single point of contact for strategic advice and issue management (anti-pattern ap-4.3-005). Option A (incorrect) is the Basic Support plan, which is free and does not include a TAM or technical support. Option B (incorrect) is the Developer Support plan, which offers email support during business hours but no TAM. Option C (incorrect) is the Business Support plan, which provides 24/7 technical support via phone, chat, and email with faster response times, but it does not include a dedicated TAM.', 63, 'm_63_3', 14, NULL, NULL),
  ('mock_60_all_1775002619521', 'A new AWS user is trying to understand how to configure an Amazon S3 bucket for static website hosting and has a few technical questions. They want to find answers quickly by searching existing resources or asking the AWS community. Which AWS resource is best suited for finding answers to common technical questions and engaging with the AWS community?', '["AWS re:Post","AWS Support Center (creating a case)","AWS Health Dashboard","AWS Professional Services"]'::jsonb, 'mcq', '{0}'::integer[], 'Option A (correct) is AWS re:Post. AWS re:Post is a community-driven Q&A service where AWS users and experts can ask and answer technical questions. It''s an excellent resource for finding answers to common configuration questions and engaging with the broader AWS community, often providing faster answers than opening a support case for well-documented issues (anti-pattern ap-4.3-004). Option B (incorrect) is the AWS Support Center for creating a case. While a valid option for complex issues, for common questions that are likely documented or previously answered, it is less efficient than self-service resources. Option C (incorrect) is the AWS Health Dashboard, which provides personalized service health notifications, not a platform for technical Q&A. Option D (incorrect) is AWS Professional Services, which provides expert consulting for large-scale projects and strategic initiatives, not a resource for answering individual technical configuration questions.', 63, 'm_63_3', 15, NULL, NULL),
  ('mock_60_all_1775002619521', 'A small development team is building a non-critical internal application and occasionally needs technical assistance for troubleshooting or general guidance. They require access to technical support engineers via email during business hours but want to keep their support costs as low as possible. Which AWS Support plan would be the MOST cost-effective choice for this team?', '["Basic Support plan","Business Support plan","Developer Support plan","Enterprise On-Ramp Support plan"]'::jsonb, 'mcq', '{2}'::integer[], 'Option C (correct) is the Developer Support plan. This plan offers technical support via email during business hours, with a typical response time of 12-24 hours for general guidance and system impaired issues. It is designed for customers who are testing or developing with AWS and need technical support but do not require 24/7 access or the fastest response times, making it the most cost-effective paid option for this scenario. Option A (incorrect) is the Basic Support plan, which is free but does not include access to technical support engineers, only customer service for account and billing questions. Option B (incorrect) is the Business Support plan, which provides 24/7 phone, chat, and email access with faster response times, but it is more expensive than the Developer plan and overkill for a non-critical internal application. Option D (incorrect) is the Enterprise On-Ramp Support plan, which is the most comprehensive and expensive plan, including a dedicated Technical Account Manager and very fast response times, far exceeding the needs and budget constraints of this development team.', 63, 'm_63_3', 16, NULL, NULL);

-- Update mock test with question count
UPDATE public.mock_tests
SET total_questions = total_questions + 16
WHERE id = 'mock_60_all_1775002619521';

